window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[335]={"id":"335","numero":335,"titre":"Traumatologie cranio-faciale","objectifs":[{"id":"335-1","rang":"A","rubrique":"Identifier une urgence","titre":"Identifier les urgences vitales et fonctionnelles du traumatisé facial","contenu":"<p>Le <span class=\"kw-clinique\">pronostic vital est rarement engagé</span> par un traumatisme maxillo-facial isolé, mais le <span class=\"kw-alerte\">pronostic fonctionnel est presque toujours en question</span>. Deux urgences vitales : l'<strong><span class=\"kw-alerte\">asphyxie</span></strong> et le <strong><span class=\"kw-alerte\">choc</span> <span class=\"kw-etio\">hémorragique</span></strong>.</p>\n      <p><strong>Urgences vitales</strong></p>\n      <table >\n        <thead><tr><th><span class=\"kw-alerte\">Urgence</span></th><th>Causes</th><th>Conduite à tenir</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Asphyxie</strong></span></td>\n            <td>Inhalation (<span class=\"kw-clinique\">sang, dents, fragments de prothèse, vomissements</span>) ; hématome compressif du plancher buccal (<span class=\"kw-etio\">fracture du corps mandibulaire</span>) ; <span class=\"kw-clinique\">glossoptose</span> (fracas mandibulaire, fracture biparasymphysaire) ; encombrement des VAS</td>\n            <td><strong>1.</strong> Libération des VAS : compresse, aspiration, canule de Mayo<br><strong>2.</strong> Si liberté non maintenue : <span class=\"kw-ttt\">intubation orotrachéale</span> (le plus souvent) ou nasotrachéale<br><strong>3.</strong> <span class=\"kw-ttt\">Trachéotomie</span> en dernier recours</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Choc hypovolémique</strong></span> (<span class=\"kw-etio\">hémorragique</span>)</td>\n            <td><span class=\"kw-clinique\">Épistaxis</span> (OPN bilatérale, zygomato-maxillaire = hémosinus unilatéral, Le Fort bilatérale) ; <span class=\"kw-clinique\">otorragie</span> (fracture os tympanal/rocher) ; <span class=\"kw-clinique\">stomatorragie</span> (corps mandibulaire) ; plaies des parties molles très hémorragiques</td>\n            <td>Compression / clampage / ligature d'un vaisseau ; <span class=\"kw-ttt\">réduction</span> de fracture + <span class=\"kw-ttt\">blocage maxillo-mandibulaire</span> ; PEC épistaxis : tamponnement antérieur, antéro-postérieur, <span class=\"kw-ttt\">embolisation de l'artère sphéno-palatine</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Dogme.</strong> Tout traumatisé facial doit être considéré comme un <span class=\"kw-alerte\">traumatisé crânien</span> et un <span class=\"kw-alerte\">traumatisé du rachis cervical</span> jusqu'à preuve du contraire. Les hémorragies peuvent être <strong>dégluties</strong> et donc sous-estimées (risque de <span class=\"kw-clinique\">vomissement</span> secondaire avec inhalation).</div>\n      <p><strong>Urgences fonctionnelles</strong> (PEC rapide en service spécialisé)</p>\n      <ul>\n        <li><strong>Ophtalmologiques :</strong> <span class=\"kw-alerte\">cécité traumatique</span> → <span class=\"kw-imagerie\">TDM en urgence</span> + décompression chirurgicale rapide (hématome/<span class=\"kw-clinique\">œdème</span> intra-orbitaire compressif, fracture du canal optique) ; <span class=\"kw-clinique\">diplopie par incarcération musculaire</span> ; plaies délabrantes des paupières</li>\n        <li><strong>Nerf facial :</strong> examen de la motricité faciale chez le patient <span class=\"kw-clinique\">vigile</span> (avant toute sédation qui masquerait l'atteinte)</li>\n        <li><strong>Pertes dentaires traumatiques :</strong> dents luxées recherchées sur le <span class=\"kw-def\">terrain</span> et conditionnées pour une éventuelle <span class=\"kw-ttt\">réimplantation</span></li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 334 — PEC immédiate trauma : polytraumatisme, brûlure, <span class=\"kw-clinique\">hypothermie</span>… · 332 — Etat de <span class=\"kw-alerte\">choc</span> · 359 — <span class=\"kw-alerte\">Détresse</span> et <span class=\"kw-ci\">insuffisance respiratoire</span> aiguë · 87 — Epistaxis</em></p>","frequence":2},{"id":"335-2","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments de l’interrogatoire et de l’examen clinique à réaliser dans le cadre d’un traumatisme facial","contenu":"<div class=\"callout callout-warn\"><strong>Valeur médico-légale.</strong> Toutes les données de l'examen clinique doivent être <span class=\"kw-alerte\">notées et datées</span> : valeur médico-légale primordiale (indemnisation du dommage corporel).</div>\n      <h4 class=\"kw-def\">Interrogatoire</h4>\n      <ul>\n        <li><strong>Circonstances :</strong> date/heure ; <span class=\"kw-etio\">agression, AVP, accident du travail / domestique / de sport, morsure</span> ; point d'impact, direction et intensité du <span class=\"kw-alerte\">choc</span></li>\n        <li><strong>Signes fonctionnels :</strong> <span class=\"kw-clinique\">craquement</span> lors du <span class=\"kw-alerte\">choc</span>, <span class=\"kw-clinique\">perte de connaissance initiale</span>, douleurs ; gênes <strong>manducatrices</strong> (modification de l'<span class=\"kw-clinique\">articulé dentaire</span>, limitation d'ouverture buccale), <strong>visuelles</strong> (BAV, <span class=\"kw-clinique\">diplopie</span>), <strong>respiratoires</strong> (obstruction nasale, anosmie, épistaxis), phonatoires</li>\n        <li><strong>ATCD :</strong> anomalie occlusale préexistante (l'<span class=\"kw-clinique\">occlusion dentaire</span> est le repère de <span class=\"kw-ttt\">réduction</span>) ; photographies prétraumatiques utiles</li>\n      </ul>\n      <h4 class=\"kw-def\">Inspection</h4>\n      <ul>\n        <li>Revêtement cutané (plaie, <span class=\"kw-clinique\">ecchymose</span>, corps étrangers) ; <span class=\"kw-clinique\">œdème</span> localisé ou « <span class=\"kw-clinique\">faciès lunaire</span> » masquant les reliefs</li>\n        <li>Hémorragie extériorisée ; <span class=\"kw-clinique\">rhinorrhée aqueuse</span> ; déformation / <span class=\"kw-clinique\">asymétrie</span> témoignant d'une fracture déplacée (savoir répéter l'inspection à distance, l'<span class=\"kw-clinique\">œdème</span> masquant les déplacements)</li>\n      </ul>\n      <h4 class=\"kw-def\">Palpation faciale (de haut en bas, finir par la zone traumatisée)</h4>\n      <table >\n        <thead><tr><th>Signes directs de fracture</th><th>Signe indirect</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">Douleur exquise</span> au trait ; déplacement osseux (<span class=\"kw-clinique\">asymétrie</span> des reliefs) ; perception d'une « <span class=\"kw-clinique\">marche d'escalier</span> » ; mobilité anormale</td>\n            <td><span class=\"kw-clinique\">Emphysème sous-cutané</span> (traduit la fracture d'une paroi de cavité aérienne) — déclenché par mouchage / éternuement / Valsalva ; topographie : sinus maxillaire, sinus frontal, cellules ethmoïdales, plancher de l'orbite</td>\n          </tr>\n        </tbody>\n      </table>\n      <h4 class=\"kw-def\">Motricité &amp; sensibilité de la face</h4>\n      <table >\n        <thead><tr><th>Nerf</th><th>Territoire / fonction</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">III</span> oculomoteur</td><td>élévateur de la paupière supérieure</td></tr>\n          <tr><td><span class=\"kw-def\">V</span> trijumeau (moteur)</td><td>muscles masticateurs</td></tr>\n          <tr><td><span class=\"kw-def\">VII</span> facial</td><td>muscles peauciers : <strong>supérieur</strong> (hausser sourcils, fermer les yeux) ; <strong>inférieur</strong> (gonfler les joues, sourire)</td></tr>\n          <tr><td><span class=\"kw-def\">V1</span> ophtalmique (sensitif)</td><td>cornée, hémifront, paupière sup., racine et dorsum du nez</td></tr>\n          <tr><td><span class=\"kw-def\">V2</span> maxillaire (sensitif)</td><td>aile nasale, partie haute de la joue, hémilèvre sup., hémiarcade dentaire supérieure</td></tr>\n          <tr><td><span class=\"kw-def\">V3</span> mandibulaire (mixte)</td><td>hémilèvre inf., menton, partie basse de la joue ; hémiarcade dentaire inf. ; 2/<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> an</span>térieurs de la langue</td></tr>\n        </tbody>\n      </table>\n      <h4 class=\"kw-def\">Examens endocavitaires &amp; examen des fonctions</h4>\n      <ul>\n        <li><strong>Fosses nasales</strong> (rhinoscopie antérieure) : épistaxis, déviation/luxation de la cloison, <span class=\"kw-alerte\">hématome de cloison</span> (à évacuer en <span class=\"kw-alerte\">urgence</span>), rhinorrhée aqueuse (brèche méningée)</li>\n        <li><strong>Cavité buccale :</strong> modification de l'<span class=\"kw-clinique\">articulé dentaire</span>, lésions dentaires (à noter, médico-légal), palpation endobuccale (mobilité de l'arcade = Le Fort, mobilité d'un secteur = fracture alvéolodentaire)</li>\n        <li><strong>CAE :</strong> caillots, plaie cutanée (fracture os tympanal), état du tympan</li>\n        <li><strong>Fonctions :</strong> manducation (ATM, occlusion, <span class=\"kw-clinique\">trismus</span>) ; ophtalmo (AV, diplopie, pupille/RPM, <span class=\"kw-clinique\">dystopie oculaire</span>) ; neuro (conscience, anosmie, rhinorrhée de <span class=\"kw-bio\">LCS</span>)</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Points QCM — discriminants.</strong> <span class=\"kw-clinique\">Hypoesthésie V2</span> = plancher de l'orbite, Le Fort 2, zygomato-maxillaire. <span class=\"kw-clinique\">Signe de Vincent (V3)</span> = corps mandibulaire déplacé (jamais une fracture symphysaire, en aval du foramen mentonnier 34-44). <span class=\"kw-clinique\">Anosmie</span> = lame criblée (CNEMFO, Le Fort 2/3). Répercussion sur l'articulé dentaire = corps/condyle mandibulaire, Le Fort 1/2/3.</div>","frequence":8},{"id":"335-3","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens à réaliser en première intention dans le cadre d’un traumatisme facial en fonction des orientations diagnostiques","contenu":"<p>Après avoir <span class=\"kw-alerte\">éliminé une lésion crânienne ou cervicale</span>, le diagnostic des fractures du massif facial fait appel à l'imagerie. La <span class=\"kw-imagerie\">TDM (scanner) non injectée</span> est l'examen de choix : haute définition, reconstructions 3D, réalisable quel que soit l'état neurologique.</p>\n      <table >\n        <thead><tr><th>Orientation</th><th>Imagerie de 1ʳᵉ intention</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Traumatisme nasal</strong></td><td><span class=\"kw-alerte\">Aucune imagerie indiquée</span> (<span class=\"kw-imagerie\">TDM</span> non injectée éventuelle à J5 si incertitude liée à l'<span class=\"kw-clinique\">œdème</span>)</td></tr>\n          <tr><td><strong>Corps mandibulaire</strong></td><td><span class=\"kw-imagerie\">Orthopantomogramme</span> (<span class=\"kw-imagerie\">panoramique dentaire</span>) ± cliché face basse ; <span class=\"kw-imagerie\">TDM</span> si doute</td></tr>\n          <tr><td><strong>Condyle mandibulaire</strong></td><td><span class=\"kw-imagerie\">Orthopantomogramme</span> + <span class=\"kw-imagerie\">incidence face basse</span> ; <span class=\"kw-imagerie\">TDM indispensable</span> à la décision thérapeutique</td></tr>\n          <tr><td><strong>Fracture zygomato-maxillaire</strong></td><td>RX <span class=\"kw-imagerie\">Blondeau, Waters, Hirtz</span> (délaissées) → <span class=\"kw-imagerie\">TDM</span> du massif facial</td></tr>\n          <tr><td><strong>Plancher de l'orbite, CNEMFO, Le Fort</strong></td><td><span class=\"kw-imagerie\">TDM indispensable</span> (coupes axiales + reconstructions coronales et sagittales centrées sur l'orbite)</td></tr>\n        </tbody>\n      </table>\n      <p>Examens biologiques : <span class=\"kw-bio\">bilan d'hémostase</span>, <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">groupage ABO-Rhésus + RAI</span> (<span class=\"kw-def\">bilan pré-opératoire</span> / hémorragie) ; <span class=\"kw-bio\">glycémie, ionogramme, alcoolémie, toxiques</span> (évaluation d'un TC associé).</p>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> L'<span class=\"kw-imagerie\">IRM</span> n'a que peu d'indications en traumatologie faciale. Le <span class=\"kw-imagerie\">Cone Beam</span> (<span class=\"kw-imagerie\">scanner</span> dentaire) peut remplacer la <span class=\"kw-imagerie\">TDM</span> (moins irradiant, moins d'artefacts métalliques, mais analyse des parties molles moins fine).</p></div>","frequence":4},{"id":"335-4","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les critères de gravité d’un traumatisme facial","contenu":"<p>La gravité se juge sur le <strong>retentissement vital, fonctionnel et l'association lésionnelle</strong>.</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Éléments de gravité</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-alerte\">Urgence</span> extrême</strong></td><td><span class=\"kw-alerte\">Hémorragie extériorisée</span> (<span class=\"kw-clinique\">stomatorragie</span>, <span class=\"kw-clinique\">épistaxis</span>, <span class=\"kw-clinique\">otorragie</span> ou plaie) ; <span class=\"kw-alerte\">cécité traumatique</span> (<span class=\"kw-imagerie\">TDM en urgence</span> ± décompression)</td></tr>\n          <tr><td><strong>Traumatisme grave</strong></td><td><span class=\"kw-alerte\">Fracture panfaciale</span> (<span class=\"kw-def\">étage moyen</span> + <span class=\"kw-def\">mandibule</span>) ; fracture irradiant aux <span class=\"kw-alerte\">confins craniofaciaux</span> avec <span class=\"kw-alerte\">complication neuroméningée</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Terrain</span> / association</strong></td><td><span class=\"kw-clinique\">Polytraumatisme</span> ; <span class=\"kw-alerte\">TC</span> et/ou <span class=\"kw-alerte\">traumatisme du rachis cervical</span> associé ; <span class=\"kw-alerte\">brèche méningée</span> ; <span class=\"kw-clinique\">atteinte fonctionnelle ophtalmologique</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Dogme.</strong> Tout traumatisé facial est un <span class=\"kw-alerte\">traumatisé crânien</span> et un <span class=\"kw-alerte\">traumatisé du rachis cervical</span> jusqu'à preuve du contraire. Dans un polytraumatisme, les priorités sont discutées avec les autres spécialistes ; les <span class=\"kw-etio\">traumatismes balistiques</span> (fracas, délabrements) associent urgences <span class=\"kw-etio\">hémorragique</span> et respiratoire.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 334 — PEC immédiate trauma : polytraumatisme, brûlure, <span class=\"kw-clinique\">hypothermie</span>… · 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":0},{"id":"335-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les déclarations obligatoires pour un patient victime d’une morsure animale","contenu":"<p>Devant toute <span class=\"kw-etio\">morsure animale</span> (<span class=\"kw-etio\">chien ++</span>), l'interrogatoire précise : animal <strong>connu / vacciné</strong> ? <span class=\"kw-clinique\">comportement inhabituel</span> ? Deux risques <span class=\"kw-etio\">infectieux</span> conditionnent les déclarations : la <span class=\"kw-alerte\">rage</span> et le <span class=\"kw-alerte\">tétanos</span>.</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Surveillance</span> vétérinaire de l'animal mordeur :</strong> obligatoire pour tout animal susceptible de transmettre la <span class=\"kw-etio\">rage</span> — <span class=\"kw-chiffre\">3 certificats vétérinaires</span> (<span class=\"kw-chiffre\">J0, J7, J14</span>) attestant l'absence de signe de rage</li>\n        <li><strong>Avis du centre antirabique :</strong> si <span class=\"kw-clinique\">animal inconnu</span>, non vaccinable, suspect ou <span class=\"kw-clinique\">comportement anormal</span> → discussion d'une <span class=\"kw-ttt\">vaccination antirabique</span> ± <span class=\"kw-ttt\">immunoglobulines</span></li>\n        <li><strong>Statut antitétanique :</strong> vérifié systématiquement → <span class=\"kw-ttt\">SAT-VAT</span> selon la couverture vaccinale (cf. plaie souillée)</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À noter.</strong> Le <span class=\"kw-clinique\">certificat médical initial</span> détaillé (<span class=\"kw-clinique\">lésions</span>, état antérieur, traitements, réserves sur le devenir) est systématique : <span class=\"kw-alerte\">valeur médico-légale</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 160 — Tétanos</em></p>","frequence":0},{"id":"335-6","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes thérapeutiques des plaies de la face (morsures incluses)","contenu":"<p>La face est <span class=\"kw-clinique\">richement vascularisée</span> : la cicatrisation est rapide mais les hémorragies sont impressionnantes. Le traitement est idéalement réalisé <span class=\"kw-chiffre\">&lt; 6 h</span>.</p>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\"><span class=\"kw-def\">Critères de</span> gravité</span> d'une plaie des parties molles.</strong> Plaie <span class=\"kw-alerte\">transfixiante</span> ; <span class=\"kw-alerte\">péri-orificielle</span> (paupières, narines, lèvres, oreilles → rétraction, ectropion, sténose) ; <span class=\"kw-alerte\">perpendiculaire aux lignes de moindre tension</span> ; <span class=\"kw-alerte\">lésion d'organe noble</span> (œil, voies lacrymales, nerf facial, conduit parotidien de Sténon) ; plaie par <span class=\"kw-alerte\">morsure</span> ; présence de <span class=\"kw-alerte\">corps étrangers</span> (fragments de pare-brise radiotransparents ++).</div>\n      <h4 class=\"kw-def\">Principes de la réparation cutanée</h4>\n      <ul>\n        <li><span class=\"kw-ttt\">Anesthésie locale</span> (plaie simple) ou <span class=\"kw-ttt\">AG</span> (plaie large, morsure, profonde) ; lavage abondant</li>\n        <li><span class=\"kw-ttt\">Suture soigneuse plan par plan</span> en minimisant le parage (la bonne vascularisation permet de conserver les petits lambeaux)</li>\n        <li>Réparation des éléments nobles au bloc ; <span class=\"kw-ttt\">SAT-VAT</span> ; <span class=\"kw-ttt\">antibioprophylaxie/antibiothérapie si plaie souillée ou morsure</span> ; ablation précoce des points (J5-7) ; <span class=\"kw-clinique\">éviction solaire 1 an</span></li>\n      </ul>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Pronostic</span> esthétique favorable</th><th>Pronostic défavorable</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>Plaie <strong>parallèle</strong> aux lignes de tension ; suture plan par plan sans décalage ni tension ; fils monobrins fins ; ablation précoce</td>\n            <td>Plaie <strong>perpendiculaire</strong> aux lignes de tension (hyperplasie, élargissement) ; phase active intense (<span class=\"kw-clinique\">enfant</span> → cicatrice large) ; <span class=\"kw-etio\">exposition solaire</span> (dyschromie définitive)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Cicatrisation de 1ʳᵉ intention : <span class=\"kw-chiffre\">5-8 jours</span> (ablation des fils). Phase active de la cicatrice : <span class=\"kw-chiffre\">≈ 1 an</span> (<span class=\"kw-chiffre\">18-24 mois</span> chez l'enfant).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 160 — Tétanos</em></p>","frequence":2},{"id":"335-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître le traumatisme dentaire nécessitant une prise en charge urgente (par exemple une luxation dentaire)","contenu":"<p>L'<span class=\"kw-alerte\">urgence</span> se définit par la nécessité d'un <strong>geste odontologique immédiat</strong> pour sauver la dent ou le germe. L'imagerie de référence est le <span class=\"kw-imagerie\">cliché rétroalvéolaire</span>.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-clinique\">Lésion</span></th><th>Clinique</th><th>Geste urgent ?</th><th>CAT</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Luxation totale</strong></span> (<span class=\"kw-ttt\">avulsion</span>)</td>\n            <td>dent <span class=\"kw-clinique\">totalement expulsée</span> de son alvéole</td>\n            <td><span class=\"kw-alerte\">Oui (&lt; 1 h)</span></td>\n            <td>Dent définitive : conservation en <strong>milieu humide</strong> (sérum + pénicilline, salive, lait à défaut) → <span class=\"kw-ttt\">réimplantation + contention</span> au plus vite. Dent lactéale : <span class=\"kw-ttt\">mainteneur d'espace</span> (PAS de réimplantation)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Luxation partielle</strong></span> (subluxation)</td>\n            <td>dent mobile, douloureuse, égressée ; saignement au collet</td>\n            <td><span class=\"kw-alerte\">Oui</span></td>\n            <td><span class=\"kw-ttt\">Réduction</span> (réimpaction) + <span class=\"kw-ttt\">contention</span> par collage aux dents adjacentes</td>\n          </tr>\n          <tr>\n            <td><strong>Fracture de l'os alvéolaire</strong></td>\n            <td><span class=\"kw-clinique\">mobilité d'un bloc</span> de dents intactes</td>\n            <td><span class=\"kw-alerte\">Oui</span></td>\n            <td><span class=\"kw-ttt\">Réduction + contention</span> du bloc</td>\n          </tr>\n          <tr>\n            <td><strong>Fracture de la couronne</strong></td>\n            <td>douloureuse, surtout si <span class=\"kw-clinique\">pulpe exposée</span> (majoration au chaud/froid)</td>\n            <td>Si exposition pulpaire</td>\n            <td>Pulpe exposée : <span class=\"kw-ttt\">dévitalisation + traitement endodontique</span> ; sinon vernis protecteur</td>\n          </tr>\n          <tr>\n            <td><em>Contusion / fracture radiculaire</em></td>\n            <td>douleur ± mobilité ; cliché normal (contusion)</td>\n            <td>Non</td>\n            <td><span class=\"kw-def\">Surveillance</span> de la <span class=\"kw-clinique\">vitalité dentaire</span> (tests thermiques/électriques répétés) ; traitement symptomatique</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Dent lactéale = ne pas réimplanter.</strong> Risque de <span class=\"kw-alerte\">lésion du germe</span> de la dent définitive sous-jacente → on préfère l'<span class=\"kw-ttt\">avulsion</span> + <span class=\"kw-ttt\">mainteneur d'espace</span>. Certificat médico-légal systématique.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 334 — PEC immédiate trauma : polytraumatisme, brûlure, <span class=\"kw-clinique\">hypothermie</span>…</em></p>","frequence":5},{"id":"335-8","rang":"B","rubrique":"Définition","titre":"Connaître la définition de la fracture de la mandibule","contenu":"<p>La <span class=\"kw-def\">mandibule</span> est le <strong>seul os mobile du massif facial</strong>. Elle comprend une <span class=\"kw-def\">portion dentée horizontale</span> (s'articulant avec les maxillaires par l'<span class=\"kw-clinique\">articulé dentaire</span>) et un <span class=\"kw-def\">ramus</span> ascendant terminé par le <span class=\"kw-def\">processus coronoïde</span> (m. temporal) et le <span class=\"kw-def\">condyle</span> (<span class=\"kw-def\">ATM</span>).</p>\n      <table >\n        <thead><tr><th>Région</th><th>Repères</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Symphyse</span></td><td>portion dentée médiane, des incisives latérales (42 → 32)</td></tr>\n          <tr><td><span class=\"kw-def\">Corps</span> (droit/gauche)</td><td>portions dentées latérales, de la canine à la 3ᵉ molaire</td></tr>\n          <tr><td><span class=\"kw-def\">Angle</span></td><td>jonction corps / branche</td></tr>\n          <tr><td><span class=\"kw-def\">Branche (ramus)</span></td><td>partie verticale ; porte coronoïde et condyle</td></tr>\n          <tr><td><span class=\"kw-def\">Unité condylienne</span></td><td>tête (intra-articulaire), col (sous-condylien haut), région sous-condylienne basse</td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong>Mécanisme :</strong> <span class=\"kw-etio\">choc direct</span> sur la portion dentée ; <span class=\"kw-etio\">traumatisme indirect</span> (<span class=\"kw-etio\">choc mentonnier</span>, bouche entrouverte) pour le condyle</li>\n        <li>Fractures <span class=\"kw-clinique\">plurifocales dans 1/3 des cas</span> ; <span class=\"kw-def\">fracture condylienne</span> souvent associée</li>\n        <li>Les fractures du corps mandibulaire sont <span class=\"kw-alerte\">ouvertes dans la cavité buccale</span> (<span class=\"kw-alerte\">risque septique</span>)</li>\n        <li>Le <span class=\"kw-def\">nerf alvéolaire inférieur (V3)</span> chemine dans le <span class=\"kw-def\">canal mandibulaire</span> et sort au <span class=\"kw-def\">foramen mentonnier</span> (en regard de <span class=\"kw-chiffre\">34-44</span>)</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Voir aussi : objectifs « signes cliniques », « examens » et « <span class=\"kw-imagerie\">TDM</span> » de la mandibule</em></p>","frequence":6,"liens":[{"href":"https://radiopaedia.org/articles/mandibular-fracture","label":"Radiopaedia : Mandibular fracture"}]},{"id":"335-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques présents dans les fractures de mandibule (pour l’ensemble des fractures, condyle inclus)","contenu":"<h4 class=\"kw-def\">Fracture du corps mandibulaire (portion dentée / angle)</h4>\n      <ul>\n        <li><strong>Symptômes :</strong> <span class=\"kw-clinique\">stomatorragie</span>, <span class=\"kw-clinique\">sialorrhée</span>, douleur à la mastication, <span class=\"kw-clinique\">trismus antalgique</span></li>\n        <li><strong>Signes :</strong> mobilité osseuse anormale ; <span class=\"kw-clinique\">plaie de la muqueuse gingivale</span> entre les 2 dents bordant le foyer ; <span class=\"kw-clinique\">modification de l'articulé dentaire</span> (chevauchement, angulation, décalage)</li>\n        <li><span class=\"kw-clinique\">Signe de Vincent</span> = hypo/anesthésie labiomentonnière (V3) si fracture déplacée en regard du canal mandibulaire (<strong>jamais</strong> dans une fracture symphysaire)</li>\n      </ul>\n      <h4 class=\"kw-def\">Fracture de la région condylienne</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Douleur préauriculaire</span> du côté fracturé ; limitation de l'ouverture buccale et de la propulsion ; <span class=\"kw-clinique\">otorragie</span> par plaie du CAE (fracture de l'os tympanal)</li>\n      </ul>\n      <table >\n        <thead><tr><th>Forme</th><th>Troubles de l'articulé</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Unilatérale</strong></td><td>raccourcissement du ramus homolatéral ; <span class=\"kw-clinique\">latérodéviation du côté fracturé</span> (ouverture, propulsion) ; <span class=\"kw-clinique\">contact molaire prématuré côté fracturé</span> + pseudobéance controlatérale</td></tr>\n          <tr><td><strong>Bilatérale</strong></td><td><span class=\"kw-clinique\">contact molaire prématuré bilatéral</span> + <span class=\"kw-clinique\">pseudobéance antérieure</span> (proche d'un Le Fort)</td></tr>\n          <tr><td><strong>Trifocale</strong></td><td>condyles bilatéraux + corps : valgisation des angles → <span class=\"kw-clinique\">élargissement du tiers inférieur de la face</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-def\">Diagnostic différentiel</span> de l'otorragie.</strong> Fracture du rocher (≠ os tympanal) si : <span class=\"kw-alerte\">hémotympan</span>, <span class=\"kw-alerte\">surdité de perception</span>, <span class=\"kw-alerte\">paralysie faciale</span>, <span class=\"kw-clinique\">vertige</span>.</div>","frequence":2},{"id":"335-10","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître le risque d’ankylose articulaire après fracture du condyle","contenu":"<p>L'<span class=\"kw-alerte\">ankylose de l'ATM</span> est la <strong>complication la plus sévère</strong> d'une fracture condylienne.</p>\n      <table >\n        <thead><tr><th>Item</th><th>Caractéristique</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Contexte</strong></td><td>survient essentiellement après une <span class=\"kw-etio\">fracture condylienne intra-articulaire</span> (tête du condyle, arrachement capsulaire)</td></tr>\n          <tr><td><strong>Clinique</strong></td><td>limitation <span class=\"kw-clinique\">progressive et chronique de l'ouverture buccale</span> (« constriction permanente des mâchoires »)</td></tr>\n          <tr><td><strong>Radiologie</strong></td><td><span class=\"kw-imagerie\">ossification progressive de la région articulaire</span></td></tr>\n          <tr><td><strong>Traitement</strong></td><td>chirurgical, avec <span class=\"kw-alerte\">forte tendance à la récidive</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Autres complications du condyle :</strong> <span class=\"kw-clinique\">troubles de l'articulé dentaire</span> (peuvent s'amender chez l'<span class=\"kw-clinique\">enfant</span> par remodelage) ; <span class=\"kw-clinique\">troubles cinétiques</span> (souvent définitifs : <span class=\"kw-chiffre\">ouverture &lt; 40 mm</span>, <span class=\"kw-clinique\">latérodéviation</span>) ; <span class=\"kw-clinique\">dysfonction de l'ATM</span> (triade <span class=\"kw-clinique\">douleur préauriculaire</span> / limitation / bruits) ; troubles de la <span class=\"kw-clinique\">croissance mandibulaire</span> chez l'enfant (<span class=\"kw-clinique\">asymétrie</span> si unilatérale, « <span class=\"kw-clinique\">profil d'oiseau</span> » si bilatérale).</p>\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-def\">Surveillance</span> prolongée chez l'enfant.</strong> Une fracture condylienne survenue dans l'enfance impose une surveillance jusqu'à la puberté (risque de trouble de croissance).</div>","frequence":2,"liens":[{"href":"https://radiopaedia.org/cases/temporomandibular-joint-ankylosis-3","label":"Radiopaedia : Ankylose de l'ATM"}]},{"id":"335-11","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens à réaliser dans le cadre d’une fracture de mandibule","contenu":"<table >\n        <thead><tr><th>Localisation</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Corps mandibulaire</strong></td>\n            <td><span class=\"kw-imagerie\">Orthopantomogramme</span> (<span class=\"kw-imagerie\">panoramique</span>) <strong>le plus souvent suffisant</strong> pour poser l'indication ± <span class=\"kw-imagerie\">cliché face basse</span> ; <span class=\"kw-imagerie\">TDM</span> (<span class=\"kw-imagerie\">coupes axiales et coronales</span>, <span class=\"kw-imagerie\">fenêtre osseuse</span>) si doute diagnostique</td>\n          </tr>\n          <tr>\n            <td><strong>Condyle</strong></td>\n            <td><span class=\"kw-imagerie\">Orthopantomogramme</span> (profil, déplacement axial) + <span class=\"kw-imagerie\">incidence face basse</span> (face, déplacement frontal) ; <span class=\"kw-imagerie\">TDM indispensable</span> à la décision thérapeutique (reconstruction 3D : hauteur du trait, taille du fragment, déplacement)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>La <span class=\"kw-imagerie\">TDM</span> confirme la (ou les) fracture(s) en précisant le <span class=\"kw-imagerie\">siège</span> et le rapport au <span class=\"kw-def\">canal mandibulaire</span>, les <span class=\"kw-imagerie\">caractéristiques du trait</span> (simple, comminutif), les <span class=\"kw-imagerie\">déplacements</span> (<span class=\"kw-imagerie\">décalage</span>, <span class=\"kw-imagerie\">angulation</span>, <span class=\"kw-imagerie\">chevauchement</span>) et l'état de la <span class=\"kw-clinique\">denture</span>.</p>","frequence":2},{"id":"335-12","rang":"B","rubrique":"Contenu multimédia","titre":"Image de tomodensitométrie d’une fracture de mandibule (coupes ou reconstruction)","contenu":"<p>Sémiologie attendue sur la <span class=\"kw-imagerie\">TDM du massif facial en fenêtre osseuse</span> (<span class=\"kw-imagerie\">coupes axiales</span> + <span class=\"kw-imagerie\">coronales</span>, <span class=\"kw-imagerie\">reconstruction 3D</span>) d'une fracture de mandibule :</p>\n      <ul>\n        <li><strong>Siège du trait :</strong> <span class=\"kw-imagerie\">symphyse, parasymphyse, corps, angle, ramus</span> ; préciser le rapport au <span class=\"kw-imagerie\">canal mandibulaire</span> (<span class=\"kw-def\">nerf alvéolaire inférieur</span>)</li>\n        <li><strong>Caractéristiques :</strong> trait <span class=\"kw-imagerie\">simple</span>, avec <span class=\"kw-imagerie\">troisième fragment</span> ou <span class=\"kw-imagerie\">comminutif</span> ; direction du biseau</li>\n        <li><strong>Déplacements :</strong> <span class=\"kw-imagerie\">décalage, angulation, chevauchement</span> des fragments dentés</li>\n        <li><strong>Reconstruction 3D :</strong> indispensable pour les <span class=\"kw-def\">fractures condyliennes</span> (<span class=\"kw-imagerie\">hauteur du trait</span>, <span class=\"kw-imagerie\">taille du fragment condylien</span>, <span class=\"kw-imagerie\">déplacement</span>) — base de la <span class=\"kw-ttt\">chirurgie</span> assistée par ordinateur</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> La fracture du corps est <span class=\"kw-alerte\">ouverte dans la cavité buccale</span> ; rechercher un <span class=\"kw-imagerie\">hémosinus</span> et un <span class=\"kw-imagerie\">emphysème</span> en cas d'atteinte d'une paroi de cavité aérienne.</div>\n      <!-- TODO Kevin : déposer une coupe TDM annotée d'une fracture mandibulaire dans assets/images/335/ (B-FIX image) -->\n      <p class=\"obj-source\"><em>Iconographie de référence : voir le lien Radiopaedia contextuel ci-dessus.</em></p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/mandibular-fracture","label":"Radiopaedia : Mandibular fracture (TDM)"}]},{"id":"335-13","rang":"B","rubrique":"Définition","titre":"Connaître la définition d’une fracture du zygoma","contenu":"<p>La <span class=\"kw-def\">fracture-disjonction du zygoma</span> (anciennement « <span class=\"kw-def\">fracture du malaire</span> ») est une fracture <span class=\"kw-def\">latérofaciale</span> par <span class=\"kw-etio\">choc direct sur la pommette</span>.</p>\n      <p>Elle associe <strong>toujours <span class=\"kw-chiffre\">3 foyers de fracture</span></strong> :</p>\n      <ul>\n        <li><span class=\"kw-def\">Apophyse frontale du zygoma</span> (<span class=\"kw-def\">suture fronto-zygomatique</span>)</li>\n        <li><span class=\"kw-def\">Apophyse temporale du zygoma</span> (coulisse temporale)</li>\n        <li><span class=\"kw-def\">Paroi antérieure du sinus maxillaire</span>, irradiant vers le <span class=\"kw-def\">cintre zygomato-maxillaire</span> (bas) et la <span class=\"kw-def\">margelle infra-orbitaire</span> / <span class=\"kw-def\">plancher de l'orbite</span> (haut)</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Fracture « ouverte ».</strong> L'atteinte des parois du <span class=\"kw-clinique\">sinus maxillaire</span> fait considérer ces fractures comme ouvertes → <span class=\"kw-alerte\">risque infectieux intra-orbitaire</span> et <span class=\"kw-alerte\">sinusite</span>.</div>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/facial-bones-waters-view","label":"Radiopaedia : incidence de Waters"}]},{"id":"335-14","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques présents dans les fractures du zygoma","contenu":"<table >\n        <thead><tr><th>Temps</th><th>Signes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Inspection</strong></td>\n            <td><span class=\"kw-clinique\">Hémorragie sous-conjonctivale</span> ; <span class=\"kw-clinique\">effacement du relief de la pommette</span> (hémiface élargie, souvent masqué par l'<span class=\"kw-clinique\">œdème</span>) ; <span class=\"kw-clinique\">décalage en « marche d'escalier »</span> au rebord orbitaire inférieur, à la suture frontozygomatique et au cintre zygomatique (vestibule supérieur)</td>\n          </tr>\n          <tr>\n            <td><strong>Palpation</strong></td>\n            <td>mobilité du corps du zygoma ; douleur exquise aux foyers ; <span class=\"kw-clinique\">emphysème sous-cutané</span> (paupière inférieure = pneumorbite, joue) déclenché par mouchage/éternuement</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Complications précoces :</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Épistaxis</span> homolatérale (<span class=\"kw-clinique\">hémosinus</span> maxillaire)</li>\n        <li><span class=\"kw-clinique\">Trismus</span> par embrochage du tendon du muscle temporal (<span class=\"kw-etio\">fracture de l'apophyse temporale</span>)</li>\n        <li><span class=\"kw-clinique\">Hypoesthésie du V2</span> : aile nasale, partie haute de la joue, hémilèvre supérieure, hémiarcade dentaire supérieure</li>\n        <li>Atteinte ophtalmologique : <span class=\"kw-clinique\">énophtalmie</span>, <span class=\"kw-clinique\">dystopie oculaire</span>, <span class=\"kw-clinique\">diplopie</span>, <span class=\"kw-clinique\">BAV</span>, <span class=\"kw-alerte\">cécité</span> (exceptionnelle)</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Forme particulière.</strong> Fracture isolée de l'apophyse temporale : <span class=\"kw-clinique\">trismus au premier plan</span>, pommette restée en place.</div>","frequence":0},{"id":"335-15","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les complications des fractures du zygoma","contenu":"<table >\n        <thead><tr><th>Type</th><th>Complications</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Précoces — ophtalmologiques</strong></td>\n            <td><span class=\"kw-clinique\">Énophtalmie</span> et <span class=\"kw-clinique\">dystopie oculaire</span> (effondrement des parois externe et inférieure de l'orbite, masqué par l'<span class=\"kw-clinique\">œdème</span>) ; <span class=\"kw-clinique\">diplopie</span> (incarcération du <span class=\"kw-clinique\">muscle droit inférieur</span> ++) ; <span class=\"kw-clinique\">BAV</span> (contusion du globe, <span class=\"kw-chiffre\">3-5 %</span>) ; <span class=\"kw-alerte\">cécité</span> exceptionnelle (<span class=\"kw-alerte\">hématome compressif</span>, <span class=\"kw-alerte\">thrombose de l'artère centrale</span>, <span class=\"kw-alerte\">contusion du nerf optique</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Précoces — autres</strong></td>\n            <td><span class=\"kw-clinique\">Hémosinus</span> / épistaxis ; <span class=\"kw-clinique\">trismus</span> ; hypoesthésie V2 ; infection intra-orbitaire (rare)</td>\n          </tr>\n          <tr>\n            <td><strong>Tardives</strong></td>\n            <td><span class=\"kw-clinique\">Séquelles morphologiques</span> (enfoncement de la pommette, énophtalmie, dystopie) ; <span class=\"kw-clinique\">diplopie résiduelle</span> (non totalement évitable) ; <span class=\"kw-clinique\">sinusites post-traumatiques</span> ; <span class=\"kw-alerte\">séquelles sensitives</span> : ≈ <span class=\"kw-chiffre\">20 %</span> des hypoesthésies V2 ne récupèrent pas → névralgies invalidantes</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 148 — Infection naso-sinusiennes</em></p>","frequence":0},{"id":"335-16","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens à réaliser dans le cadre d’une fracture du zygoma","contenu":"<ul>\n        <li><strong>Examen ophtalmologique initial obligatoire</strong> (<span class=\"kw-alerte\">médico-légal</span>) : <span class=\"kw-bio\">acuité visuelle</span>, <span class=\"kw-bio\">fond d'œil</span>, <span class=\"kw-bio\">test de Lancaster</span></li>\n        <li><span class=\"kw-imagerie\">TDM du massif facial</span> = référence : <span class=\"kw-imagerie\">coupes osseuses millimétriques</span> + <span class=\"kw-imagerie\">reconstruction 3D</span>, <strong>non injectée</strong>, dans un délai <span class=\"kw-chiffre\">&lt; 48-72 h</span></li>\n        <li>RX (<span class=\"kw-imagerie\">Blondeau, Waters, Hirtz</span>) : <span class=\"kw-imagerie\">signes directs et indirects</span>, mais délaissées au profit du <span class=\"kw-imagerie\">scanner</span></li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> relative.</strong> En présence de <span class=\"kw-alerte\">signes de gravité</span> — <span class=\"kw-alerte\">BAV</span>, <span class=\"kw-alerte\">limitation de l'oculomotricité</span> évoquant une <span class=\"kw-alerte\">atteinte des parois orbitaires</span> — la <span class=\"kw-imagerie\">TDM</span> et l'avis ophtalmologique deviennent <strong>urgents</strong> (et non différés à<span class=\"kw-chiffre\"> 48-72 h</span>).</div>","frequence":0},{"id":"335-17","rang":"B","rubrique":"Définition","titre":"Connaître la définition d’une fracture du plancher de l’orbite","contenu":"<p>Fracture par <span class=\"kw-etio\">mécanisme indirect</span> : un <span class=\"kw-etio\">choc antéropostérieur sur le globe oculaire</span> crée une <span class=\"kw-etio\">hyperpression intra-orbitaire</span> qui fracture le <span class=\"kw-def\">plancher</span> (<span class=\"kw-def\">paroi la plus vulnérable</span>, très faible épaisseur) ± la <span class=\"kw-def\">paroi médiale</span>.</p>\n      <p>Deux entités à distinguer impérativement :</p>\n      <table >\n        <thead><tr><th></th><th>Fracture en trappe</th><th>Fracture « blow-out »</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Terrain</span></strong></td><td><span class=\"kw-clinique\">Enfant</span> (os « plastique »)</td><td><span class=\"kw-clinique\">Adulte</span></td></tr>\n          <tr><td><strong>Mécanisme</strong></td><td>fracture arciforme <span class=\"kw-imagerie\">en bois vert</span> → trappe qui s'ouvre, ptose puis <span class=\"kw-alerte\">incarcération de la périorbite</span> (<span class=\"kw-clinique\">graisse</span> ± <span class=\"kw-clinique\">muscle droit inférieur</span>) à la refermeture</td><td>plancher largement ouvert dans le <span class=\"kw-clinique\">sinus maxillaire</span>, ± comminutif. <em>Pur</em> = <span class=\"kw-def\">margelle infra-orbitaire intacte</span> ; <em>impur</em> = margelle fracturée</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Distinction clé.</strong> La <span class=\"kw-alerte\">trappe de l'enfant</span> = <span class=\"kw-alerte\">urgence</span> (incarcération musculaire) ; le <span class=\"kw-clinique\">blow-out de l'adulte</span> = rarement urgent (incarcération improbable).</div>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/trapdoor-fracture-1","label":"Radiopaedia : Trapdoor fracture"},{"href":"https://radiopaedia.org/articles/orbital-blow-out-fracture-2","label":"Radiopaedia : Orbital blow-out fracture"}]},{"id":"335-18","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques présents dans les fractures du plancher de l’orbite","contenu":"<table >\n        <thead><tr><th></th><th>Fracture en trappe (enfant)</th><th>Blow-out (adulte)</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Signes spécifiques</strong></td>\n            <td><span class=\"kw-alerte\">Syndrome vagal</span> (<span class=\"kw-clinique\">vomissements</span>, <span class=\"kw-clinique\">douleur intense</span>) ; <span class=\"kw-alerte\">ophtalmoplégie verticale totale et douloureuse</span></td>\n            <td><span class=\"kw-clinique\">Limitation de l'élévation</span> dans le regard vers le haut <strong>sans</strong> ophtalmoplégie totale ; <span class=\"kw-clinique\">énophtalmie</span> ± <span class=\"kw-clinique\">dystopie</span> (tardives, après disparition de l'<span class=\"kw-clinique\">œdème</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Signes communs aux deux types</strong> (inconstants) :</p>\n      <ul>\n        <li>Signes indirects : <span class=\"kw-clinique\">œdème / ecchymose périorbitaire</span>, <span class=\"kw-clinique\">chémosis</span>, <span class=\"kw-clinique\">hémorragie conjonctivale</span>, <span class=\"kw-clinique\">emphysème palpébral</span></li>\n        <li><span class=\"kw-clinique\">Hypoesthésie du nerf infra-orbitaire (V2)</span> : lèvre supérieure, joue, aile du nez</li>\n        <li><span class=\"kw-clinique\">Diplopie verticale binoculaire</span></li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Piège sémiologique.</strong> Il n'y a <span class=\"kw-alerte\">pas de douleur à la palpation des reliefs osseux</span> (≠ fractures latérofaciales). Le diagnostic repose sur la <span class=\"kw-clinique\">diplopie</span>, l'<span class=\"kw-clinique\">hypoesthésie V2</span> et l'<span class=\"kw-imagerie\">imagerie</span>.</div>","frequence":6,"liens":[{"href":"https://radiopaedia.org/articles/orbital-blow-out-fracture-2","label":"Radiopaedia : Orbital blow-out fracture"}]},{"id":"335-19","rang":"A","rubrique":"Identifier une urgence","titre":"Reconnaître les critères d’incarcération musculaire dans une fracture du plancher de l’orbite","contenu":"<p>L'incarcération du <span class=\"kw-alerte\">muscle droit inférieur</span> dans une fracture en trappe est la <strong>seule <span class=\"kw-alerte\">urgence</span> vraie</strong> de la traumatologie orbitaire.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Critères cliniques</span></th><th>Critères <span class=\"kw-imagerie\">TDM</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\">Syndrome vagal</span> (<span class=\"kw-clinique\">vomissements</span>, <span class=\"kw-clinique\">douleur intense</span>, <span class=\"kw-clinique\">bradycardie</span>) ; <span class=\"kw-alerte\">ophtalmoplégie verticale totale et douloureuse</span> ; <span class=\"kw-clinique\">limitation de l'élévation du regard</span></td>\n            <td>Trait de fracture <span class=\"kw-imagerie\">peu visible</span> (trappe « refermée ») ; <span class=\"kw-imagerie\">incarcération musculo-graisseuse</span> donnant une <span class=\"kw-imagerie\">image en sablier</span> en coupe coronale</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> thérapeutique.</strong> En l'absence de prise en charge <span class=\"kw-chiffre\">dans les heures qui suivent</span> : <span class=\"kw-alerte\">fibrose musculaire par ischémie</span> → <span class=\"kw-alerte\">diplopie séquellaire</span> le plus souvent <strong>définitive</strong>, et risque d'<span class=\"kw-alerte\">amblyopie majeur chez l'enfant</span>. <span class=\"kw-ci\">Mouchage contre-indiqué</span>.</div>","frequence":2},{"id":"335-20","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens à réaliser en urgence dans le cadre d’une fracture du plancher de l’orbite","contenu":"<ul>\n        <li><strong>Examen ophtalmologique :</strong> <span class=\"kw-bio\">acuité visuelle</span>, <span class=\"kw-bio\">fond d'œil</span>, <span class=\"kw-bio\">test de Lancaster</span> ; <span class=\"kw-clinique\">oculomotricité</span></li>\n        <li><strong><span class=\"kw-imagerie\">Scanner du massif facial non injecté</span></strong> — signes communs (inconstants) :\n          <ul>\n            <li><span class=\"kw-imagerie\">Rupture de la continuité du plancher</span></li>\n            <li><span class=\"kw-imagerie\">Hémosinus maxillaire</span></li>\n            <li><span class=\"kw-imagerie\">Pneumorbite</span></li>\n            <li><span class=\"kw-imagerie\">Image en sablier</span> (<span class=\"kw-imagerie\">coupe coronale</span>) si <span class=\"kw-alerte\">incarcération musculaire</span></li>\n          </ul>\n        </li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Place du test de Lancaster.</strong> Il objective l'<span class=\"kw-clinique\">oculomotricité</span> mais <strong>ne doit PAS être réalisé en <span class=\"kw-alerte\">urgence</span></strong> chez un patient avec <span class=\"kw-alerte\">incarcération</span> et <span class=\"kw-alerte\">ophtalmoplégie douloureuse</span> (retarderait la <span class=\"kw-ttt\">chirurgie</span>, irréalisable du fait de la douleur). Le Lancaster se fait en <span class=\"kw-clinique\">pré-opératoire en l'absence d'incarcération</span>, puis en post-opératoire / <span class=\"kw-def\">suivi</span>.</div>","frequence":2},{"id":"335-21","rang":"B","rubrique":"Contenu multimédia","titre":"Scanner d’une fracture du plancher de l’orbite","contenu":"<p>Sémiologie attendue sur le <span class=\"kw-imagerie\">scanner du massif facial non injecté</span> (<span class=\"kw-imagerie\">reconstructions coronales et sagittales</span> centrées sur l'orbite) :</p>\n      <table >\n        <thead><tr><th>Type</th><th>Signes <span class=\"kw-imagerie\">TDM</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Fracture en trappe</strong></td>\n            <td>trait <span class=\"kw-imagerie\">peu visible</span> (<span class=\"kw-imagerie\">trappe refermée</span>) ; <span class=\"kw-imagerie\">incarcération musculo-graisseuse</span> → <span class=\"kw-imagerie\">image en sablier</span> en <span class=\"kw-imagerie\">coupe coronale</span></td>\n          </tr>\n          <tr>\n            <td><strong>Blow-out</strong></td>\n            <td><span class=\"kw-imagerie\">effondrement du plancher</span> ± <span class=\"kw-imagerie\">comminution</span> ; <span class=\"kw-imagerie\">hernie du muscle droit inférieur</span> et de la <span class=\"kw-imagerie\">graisse</span> dans le <span class=\"kw-clinique\">sinus maxillaire</span></td>\n          </tr>\n          <tr>\n            <td><strong>Signes communs</strong></td>\n            <td><span class=\"kw-imagerie\">rupture du plancher</span>, <span class=\"kw-imagerie\">hémosinus maxillaire</span>, <span class=\"kw-imagerie\">pneumorbite</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <!-- TODO Kevin : déposer une coupe coronale TDM (trappe « en sablier » + blow-out) dans assets/images/335/ (B-FIX image) -->\n      <p class=\"obj-source\"><em>Iconographie de référence : voir les liens Radiopaedia contextuels ci-dessus.</em></p>","frequence":4,"liens":[{"href":"https://radiopaedia.org/articles/trapdoor-fracture-1","label":"Radiopaedia : Trapdoor fracture (TDM)"},{"href":"https://radiopaedia.org/articles/orbital-blow-out-fracture-2","label":"Radiopaedia : Blow-out (TDM)"}]},{"id":"335-22","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement d’une fracture du plancher de l’orbite avec incarcération musculaire","contenu":"<p>Toujours : <span class=\"kw-ttt\">antalgiques</span> et <span class=\"kw-ci\">contre-indication au mouchage</span>.</p>\n      <table >\n        <thead><tr><th>Forme</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Trappe avec incarcération</strong></span></td>\n            <td><span class=\"kw-alerte\">Urgence chirurgicale</span> (<span class=\"kw-chiffre\">&lt; 6 h</span> idéalement) :<br><strong>1.</strong> abord transconjonctival ou transcutané<br><strong>2.</strong> <span class=\"kw-ttt\">décollement sous-périosté pour libérer le muscle</span> (désincarcération)<br><strong>3.</strong> <span class=\"kw-ttt\">reconstruction du plancher</span><br>+ <span class=\"kw-ttt\">antibioprophylaxie</span> ; <span class=\"kw-ttt\">test de duction forcée</span> pré- et post-désincarcération sous AG</td>\n          </tr>\n          <tr>\n            <td><strong>Effondrement / blow-out</strong></td>\n            <td>traitement <span class=\"kw-clinique\">à distance</span> (<span class=\"kw-chiffre\">2-21 jours</span>) : si <span class=\"kw-clinique\">énophtalmie résiduelle</span> ou persistance d'un <span class=\"kw-clinique\">trouble oculomoteur</span> / <span class=\"kw-clinique\">diplopie</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Le délai fait le <span class=\"kw-def\">pronostic</span>.</strong> Toute <span class=\"kw-alerte\">incarcération</span> non levée rapidement évolue vers une <span class=\"kw-alerte\">diplopie séquellaire définitive</span> (fibrose <span class=\"kw-etio\">ischémique</span>) — <span class=\"kw-alerte\">amblyopie chez l'enfant</span>.</div>","frequence":1},{"id":"335-23","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques présents dans les fractures des os nasaux","contenu":"<p>Fracture la <strong>plus fréquente de la face</strong> ; <span class=\"kw-etio\">choc antéropostérieur ou latéral direct</span> sur le nez ; <span class=\"kw-def\">terrain</span> : homme de <span class=\"kw-chiffre\">20-30 ans</span>.</p>\n      <table >\n        <thead><tr><th>Temps</th><th>Signes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Symptômes</strong></td>\n            <td><span class=\"kw-clinique\">Craquement</span>, douleur ; <span class=\"kw-clinique\">épistaxis bilatérale</span> (plaie muqueuse endonasale = caractère ouvert) ; <span class=\"kw-clinique\">obstruction nasale</span></td>\n          </tr>\n          <tr>\n            <td><strong>Inspection</strong></td>\n            <td><span class=\"kw-clinique\">Hématome du dorsum</span>, <span class=\"kw-clinique\">ecchymose en lunettes</span> ; déformation : <span class=\"kw-clinique\">nez couché</span> (<span class=\"kw-alerte\">choc</span> latéral) ou <span class=\"kw-clinique\">ensellure nasale</span> (choc antéro-postérieur), souvent masquée par l'<span class=\"kw-clinique\">œdème</span></td>\n          </tr>\n          <tr>\n            <td><strong>Examen</strong></td>\n            <td><span class=\"kw-clinique\">Douleur élective</span>, <span class=\"kw-clinique\">mobilité « en touche de piano »</span> ; rhinoscopie antérieure : <span class=\"kw-clinique\">luxation de la cloison</span>, <span class=\"kw-clinique\">épistaxis</span>, <span class=\"kw-alerte\">hématome de la cloison</span> (<span class=\"kw-alerte\">urgence</span>), <span class=\"kw-alerte\">rhinoliquorrhée</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Forme particulière.</strong> Fracture nasomaxillaire (os nasaux + apophyses frontales des maxillaires) : « marche d'escalier » palpable à la partie médiale du rebord infra-orbitaire.</div>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/nasal-bone-fracture","label":"Radiopaedia : Nasal bone fracture"}]},{"id":"335-24","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les critères de gravité d’une fracture des os nasaux (hématome cloison, épistaxis)","contenu":"<div class=\"callout callout-danger\"><strong>Deux urgences à éliminer systématiquement :</strong> l'<span class=\"kw-alerte\">épistaxis massive</span> et l'<span class=\"kw-alerte\">hématome de cloison</span>.</div>\n      <table >\n        <thead><tr><th><span class=\"kw-alerte\"><span class=\"kw-def\">Critère de</span> gravité</span></th><th>Détail / CAT</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Hématome de cloison</strong></span></td>\n            <td><span class=\"kw-clinique\">obstruction complète de la fosse nasale</span> (décollement de la muqueuse septale), <strong>mou</strong> à la palpation, hématome vestibulaire de la lèvre supérieure → risque de <span class=\"kw-alerte\">nécrose septale</span> et de <span class=\"kw-alerte\">surinfection</span>. CAT : <span class=\"kw-ttt\">mise à plat / drainage en urgence au bloc</span> (la <span class=\"kw-ttt\">ponction</span> est insuffisante : recollection) + contention (lame de Silastic + méchage)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>Épistaxis massive / bilatérale</strong></span></td>\n            <td>signe le caractère ouvert ; PEC selon abondance (tamponnement, embolisation)</td>\n          </tr>\n          <tr>\n            <td><strong>Rhino-liquorrhée</strong></td>\n            <td>évoque une <span class=\"kw-alerte\">brèche méningée</span> (fractures complexes, <span class=\"kw-etio\">Le Fort 3</span> associée) → <span class=\"kw-imagerie\">TDM cérébrale et du massif facial</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Séquelles :</strong> <span class=\"kw-clinique\">esthétiques</span> (déformation de la pyramide → <span class=\"kw-ttt\">rhinoplastie</span> à <span class=\"kw-chiffre\">1 an</span>) ; <span class=\"kw-clinique\">fonctionnelles</span> (<span class=\"kw-clinique\">déviation de la cloison</span> ou <span class=\"kw-clinique\">perforation</span> par <span class=\"kw-clinique\">nécrose</span> d'un hématome négligé → <span class=\"kw-ttt\">septoplastie</span>).</p>","frequence":0},{"id":"335-25","rang":"B","rubrique":"Définition","titre":"Connaître la définition des fractures de Le Fort","contenu":"<p>Les <span class=\"kw-def\">fractures de Le Fort</span> (fractures-disjonction cranio-faciales / occluso-faciales) résultent d'un <span class=\"kw-etio\">traumatisme à haute cinétique</span>. Elles séparent l'<span class=\"kw-clinique\">arcade dentaire maxillaire</span> de la <span class=\"kw-def\">base du crâne</span> à une <span class=\"kw-chiffre\">hauteur variable</span> et induisent un <span class=\"kw-clinique\">trouble de l'occlusion dentaire</span>.</p>\n      <div class=\"callout callout-warn\"><strong>Pathognomonique.</strong> En postérieur, la <span class=\"kw-alerte\">fracture des processus ptérygoïdes du sphénoïde</span> est systématique et <strong>obligatoire</strong> pour porter le diagnostic de Le Fort (interruption de la <span class=\"kw-def\">suture ptérygo-maxillaire</span> → <span class=\"kw-clinique\">mobilité du massif facial moyen</span>). En antérieur, c'est la <strong>hauteur du trait</strong> qui définit le type I, II ou III.</div>\n      <table >\n        <thead><tr><th>Type</th><th>Détachement</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Le Fort I</span></td><td>détache le <strong>plateau palatin</strong> seul (trait horizontal au ras de l'orifice piriforme)</td></tr>\n          <tr><td><span class=\"kw-def\">Le Fort II</span></td><td>détache de manière solidaire <strong>plateau palatin + pyramide nasale</strong> (trait pyramidal : os nasaux, planchers orbitaires, cintres zygomato-maxillaires)</td></tr>\n          <tr><td><span class=\"kw-def\">Le Fort III</span></td><td><strong>disjonction cranio-faciale complète</strong> (parois médiales + latérales des orbites, processus des zygomatiques)</td></tr>\n        </tbody>\n      </table>\n      <p>Par définition <span class=\"kw-chiffre\">bilatérales</span> (sinon « <span class=\"kw-def\">hémi-Le Fort</span> ») ; toutes les associations sont possibles. <span class=\"kw-def\">Fracture panfaciale</span> = Le Fort + <span class=\"kw-def\">fracture mandibulaire</span>.</p>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/le-fort-fracture-classification","label":"Radiopaedia : Le Fort fracture classification"}]},{"id":"335-26","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques communs et spécifiques des différents types des fractures de Le Fort","contenu":"<h4 class=\"kw-def\">Signes communs aux trois types</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Trouble de l'occlusion dentaire</span> : <strong><span class=\"kw-clinique\">contacts molaires prématurés bilatéraux</span> + <span class=\"kw-clinique\">pseudobéance antérieure</span></strong> (recul et bascule du plateau palatin), aspect figé, bouche entrouverte</li>\n        <li><span class=\"kw-clinique\">Épistaxis fréquente</span>, parfois massive (plaies muqueuses, <span class=\"kw-clinique\">hémosinus</span>) ; <span class=\"kw-alerte\">risque infectieux</span> (fractures ouvertes)</li>\n      </ul>\n      <table >\n        <thead><tr><th>Type</th><th>Signes spécifiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Le Fort I</strong></td>\n            <td><span class=\"kw-clinique\">Ecchymose</span> en « <span class=\"kw-clinique\">fer à cheval</span> » au fond du vestibule supérieur ; <span class=\"kw-clinique\">mobilité isolée du plateau palatin</span> ; reste de la face normal (<strong>pyramide nasale et zygomas stables</strong>)</td>\n          </tr>\n          <tr>\n            <td><strong>Le Fort II</strong></td>\n            <td>Effondrement de la pyramide nasale, <span class=\"kw-clinique\">ecchymose en lunettes</span>, emphysème périorbitaire ; mobilité du palais + <strong>pyramide nasale</strong> ; <strong>zygomas stables</strong> ; marches d'escalier aux margelles infra-orbitaires ; <span class=\"kw-clinique\">hypoesthésie V2</span></td>\n          </tr>\n          <tr>\n            <td><strong>Le Fort III</strong></td>\n            <td>Faciès « lunaire », effacement de la racine du nez ; <strong>zygomas mobiles</strong> ; douleur aux sutures frontozygomatiques et processus temporaux ; souvent associé à d'autres fractures</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Complications précoces (LF2/3) :</strong> <span class=\"kw-clinique\">larmoiement</span>, <span class=\"kw-clinique\">anosmie</span> (lame criblée), <span class=\"kw-clinique\">diplopie</span>, troubles visuels, <span class=\"kw-alerte\">rhinorrhée cérébrospinale</span> (brèche dure-mérienne → <span class=\"kw-alerte\">méningite</span>).</p>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/le-fort-fracture-classification","label":"Radiopaedia : Le Fort fracture classification"}]},{"id":"335-27","rang":"B","rubrique":"Identifier une urgence","titre":"Connaître des risques fonctionnels et vitaux des fractures de Le Fort","contenu":"<table >\n        <thead><tr><th>Risques vitaux</th><th>Risques fonctionnels</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <span class=\"kw-alerte\">Épistaxis massive</span> → <span class=\"kw-alerte\">choc hémorragique</span><br>\n              <span class=\"kw-alerte\">Asphyxie</span> (encombrement, recul du massif)<br>\n              <span class=\"kw-alerte\">Méningite</span> sur <span class=\"kw-alerte\">brèche dure-mérienne</span> (LF2/3)\n            </td>\n            <td>\n              <span class=\"kw-clinique\">Rhinorrhée cérébrospinale</span> (<span class=\"kw-clinique\">irradiation</span> à l'étage antérieur de la base)<br>\n              <span class=\"kw-alerte\">Cécité</span> / <span class=\"kw-clinique\">troubles visuels</span> (contusion des globes, <span class=\"kw-alerte\">atteinte du nerf optique</span> par compression ou au canal optique)<br>\n              <span class=\"kw-clinique\">Diplopie</span> ; <span class=\"kw-clinique\">anosmie</span> (lame criblée) ; <span class=\"kw-clinique\">hypoesthésie V2</span> ; <span class=\"kw-clinique\">larmoiement</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Dogme.</strong> Toute fracture de Le Fort impose de considérer le patient comme un <span class=\"kw-alerte\">traumatisé crânien</span> (violence du <span class=\"kw-alerte\">choc</span>) ; rechercher une <span class=\"kw-alerte\">brèche ostéoméningée</span> devant toute rhinorrhée claire.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 151 — Méningite - méningoencéphalite · 87 — Epistaxis</em></p>","frequence":0},{"id":"335-28","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les éléments cliniques d’une brèche cérébro-spinale dans le cadre d’un traumatisme facial","contenu":"<p>La <span class=\"kw-def\">brèche ostéoméningée (BOM)</span> = fracture de la base du crâne + déchirure de la dure-mère mettant en <strong>communication directe</strong> les espaces méningés avec les cavités aériennes (sinus paranasaux, oreille moyenne) et donc le milieu extérieur.</p>\n      <p>À rechercher devant tout TC associé à un traumatisme de l'étage moyen de la face (<span class=\"kw-etio\">Le Fort 2/3, CNEMFO, os nasaux</span>) :</p>\n      <ul>\n        <li><span class=\"kw-alerte\">Rhinorrhée de LCS</span> : écoulement clair « eau de roche », recherché <strong>tête penchée en avant</strong> ou à la <strong>manœuvre de Valsalva</strong> ; confirmation par <span class=\"kw-bio\">glucose à la bandelette</span> ou, plus spécifique, <span class=\"kw-bio\">β2-transferrine / protéine tau / β-trace</span></li>\n        <li><span class=\"kw-clinique\">Ecchymose « en lunettes »</span> ; <span class=\"kw-clinique\">anosmie</span> (section des filets olfactifs, fracture de l'ethmoïde)</li>\n        <li><span class=\"kw-imagerie\">Pneumencéphalie</span> (air intradural) ; trait de fracture sur la paroi postérieure du sinus frontal, l'ethmoïde ou le sinus sphénoïdal</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Risque majeur = <span class=\"kw-alerte\">méningite</span></strong> (<span class=\"kw-etio\">pneumocoque</span>, <em><span class=\"kw-etio\">Haemophilus influenzae</span></em>) → empyème, <span class=\"kw-clinique\">abcès</span>. CAT : <span class=\"kw-ttt\">vaccination anti-pneumocoque + anti-Haemophilus</span> et <span class=\"kw-imagerie\">TDM en urgence</span>.</div>\n      <div class=\"callout callout-info\"><strong>Cas particulier — fracture du rocher :</strong> <span class=\"kw-clinique\">ecchymose rétromastoïdienne</span>, <span class=\"kw-clinique\">otoliquorrhée / otorragie</span>, hypoacousie, <span class=\"kw-clinique\">paralysie faciale périphérique</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 151 — Méningite - méningoencéphalite</em></p>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/csf-rhinorrhoea","label":"Radiopaedia : CSF rhinorrhoea"}]},{"id":"335-29","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens à réaliser dans le cadre d’une fracture de Le Fort","contenu":"<ul>\n        <li><span class=\"kw-imagerie\">Scanner craniofacial non injecté</span> en <span class=\"kw-imagerie\">coupes millimétriques</span> avec <span class=\"kw-imagerie\">reconstructions dans les 3 plans</span> :\n          <ul>\n            <li><strong>Axiales :</strong> région centrofaciale / <span class=\"kw-def\">CNEMFO</span>, cellules ethmoïdales, parois du sinus frontal, <span class=\"kw-imagerie\">canal optique</span></li>\n            <li><strong>Coronales :</strong> <span class=\"kw-imagerie\">parois de l'orbite</span>, base du crâne</li>\n            <li><strong>Sagittales :</strong> parois supérieure et inférieure de l'orbite, base du crâne</li>\n          </ul>\n        </li>\n        <li>Préciser les traits de fracture, explorer les <span class=\"kw-imagerie\">structures orbitaires et ethmoïdales</span> (<span class=\"kw-imagerie\">labyrinthes, lame criblée</span>), <strong>éliminer une <span class=\"kw-alerte\">lésion neurochirurgicale associée</span></strong></li>\n        <li>Le <span class=\"kw-imagerie\">pneumorbite</span> fait suspecter une <span class=\"kw-imagerie\">fracture des parois orbitaires</span> (<span class=\"kw-def\">Le Fort II et/ou III</span>)</li>\n        <li>Bilan <span class=\"kw-ttt\">biologique</span> pré-opératoire : <span class=\"kw-bio\">hémostase</span>, <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">groupage-RAI</span></li>\n      </ul>","frequence":2},{"id":"335-30","rang":"A","rubrique":"Définition","titre":"Connaître les différents traumatismes crâniens de l’enfant","contenu":"<p>Les TC sont très fréquents et le plus souvent <span class=\"kw-clinique\">bénins</span> chez l'enfant (&lt;<span class=\"kw-chiffre\"> 10-12 ans</span>), mais ils sont la <span class=\"kw-alerte\">1ʳᵉ cause de mortalité et de handicap sévère du grand enfant</span> (<span class=\"kw-chiffre\">15-18 ans</span>). Des <strong>particularités anatomo-physiologiques</strong> les distinguent de l'adulte.</p>\n      <table >\n        <thead><tr><th>Particularité</th><th>Conséquence</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Disproportion crâne-corps</strong></td><td>inertie de la tête → <span class=\"kw-alerte\">arrachement des veines « en pont »</span> (lésions du bébé secoué) — facteur aggravant</td></tr>\n          <tr><td><strong>Immaturité cérébrale</strong></td><td>cerveau peu myélinisé, mal protégé contre l'<span class=\"kw-alerte\">ischémie</span> et les <span class=\"kw-alerte\">convulsions</span> (aggravant) ; mais <span class=\"kw-clinique\">plasticité</span> = bonne récupération des lésions primaires</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Masse</span> sanguine faible</strong></td><td>plaie du scalp / <span class=\"kw-clinique\">céphalhématome</span> → <span class=\"kw-alerte\">choc hémorragique</span> possible avant les signes neurologiques</td></tr>\n          <tr><td><strong>Immaturité squelettique</strong></td><td>crâne souple → <span class=\"kw-clinique\">contusion sous-fracturaire</span> ; <span class=\"kw-alerte\">fracture évolutive</span> = fracture + déchirure durale + hernie cérébrale qui s'aggrave avec la croissance</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Trois cadres :</strong></p>\n      <ul>\n        <li><strong>TC accidentel :</strong> <span class=\"kw-clinique\">céphalhématome</span> (collection limitée par les sutures), <span class=\"kw-clinique\">fracture linéaire simple</span> → <span class=\"kw-clinique\">embarrure</span></li>\n        <li><strong>TC obstétrical :</strong> céphalhématome (<span class=\"kw-clinique\">lésion</span> la plus fréquente, <span class=\"kw-chiffre\">0,5-1,5 %</span>, guérison spontanée), fractures favorisées par le <span class=\"kw-etio\">forceps</span></li>\n        <li><strong>TC non accidentel :</strong> <span class=\"kw-alerte\">syndrome du bébé secoué</span> (cf. objectif gravité)</li>\n      </ul>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de neurochirurgie (chapitre item 335, particularités pédiatriques).</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 57 — Maltraitance, enfant en danger</em></p>","frequence":0},{"id":"335-31","rang":"A","rubrique":"Identifier une urgence","titre":"Traumatismes crâniens de l’enfant : évaluer la gravité et les complications précoces","contenu":"<h4 class=\"kw-def\">Signes spécifiques de gravité chez l'enfant</h4>\n      <p>Évoquer une <span class=\"kw-alerte\">souffrance cérébrale / HTIC</span> devant :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Contact visuel</span> : regard « en coucher de soleil », errance du regard, perte du contact oculaire</li>\n        <li><span class=\"kw-clinique\">Fontanelle antérieure bombante</span> (présente jusqu'à<span class=\"kw-chiffre\"> 15-18 mois</span>) — à palper systématiquement</li>\n        <li><span class=\"kw-clinique\">Bradycardie</span> (peut traduire une <span class=\"kw-alerte\">HTIC</span>)</li>\n        <li><span class=\"kw-alerte\">Pâleur et signes de choc hémorragique</span> → demander une <span class=\"kw-bio\">NFS</span> (perte sanguine sur scalp/céphalhématome)</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Syndrome du bébé secoué (SBS)</strong> — <span class=\"kw-def\">mortalité</span> ≈ <span class=\"kw-chiffre\">10 %</span>, nourrisson &lt;<span class=\"kw-chiffre\"> 1 an</span> (2/3 &lt;<span class=\"kw-chiffre\"> 6 mois</span>). Décélérations antéropostérieures → arrachement des veines « en pont » → <span class=\"kw-alerte\">hématome sous-dural</span>.<br>\n        <strong>Clinique :</strong> troubles de la vigilance / <span class=\"kw-alerte\">coma</span>, <span class=\"kw-alerte\">convulsions</span>, signes d'<span class=\"kw-alerte\">HTIC</span> (macrocrânie, fontanelle bombante, <span class=\"kw-clinique\">vomissements</span>, strabisme, régression psychomotrice), hypotonie axiale, <span class=\"kw-clinique\">signes cutanés</span> (<span class=\"kw-clinique\">ecchymoses</span> à photographier), lésions ORL.<br>\n        <strong>Bilan :</strong> <span class=\"kw-imagerie\">scanner cérébral</span> (HSD), <span class=\"kw-bio\">fond d'œil précoce</span> (<span class=\"kw-alerte\">hémorragies rétiniennes</span> caractéristiques, disparaissent en <span class=\"kw-chiffre\">1 semaine</span>), <span class=\"kw-imagerie\">IRM</span>, radiographies du squelette entier, <span class=\"kw-bio\">NFS / hémostase</span>.</div>\n      <div class=\"callout callout-warn\"><strong>Obligation légale.</strong> Tout <span class=\"kw-alerte\">hématome sous-dural du nourrisson doit faire évoquer une maltraitance</span>. Le <strong>signalement judiciaire</strong> est une obligation qui dégage le médecin du secret médical.</div>\n      <p><strong>Complications précoces communes :</strong> hématome extra-dural / sous-dural, fracture évolutive (déchirure durale), embarrure, <span class=\"kw-alerte\">œdème cérébral</span>, <span class=\"kw-alerte\">convulsions</span>.</p>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de neurochirurgie (chapitre item 335, particularités pédiatriques).</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 57 — Maltraitance, enfant en danger</em></p>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/facial-fractures","label":"Radiopaedia : Facial fractures (vue d'ensemble)"},{"href":"https://campus.neurochirurgie.fr/article1788.html","label":"Campus Neurochirurgie : Traumatisme crânien"},{"href":"https://radiopaedia.org/cases/teaching-head-ct-with-annotated-scrollable-images","label":"Radiopaedia : scanner cérébral annoté (anatomie)"}],"cards":[{"i":"00bb212c9fee","n":335,"o":"335-1","u":"Identifier une urgence","t":"Identifier les urgences vitales et fonctionnelles du traumatisé facial","q":"Quelles sont les principales urgences fonctionnelles à considérer après un traumatisme facial ?","a":"<p>Les urgences fonctionnelles nécessitant une prise en charge rapide en service spécialisé sont :</p><ul><li><strong>Urgences ophtalmologiques</strong> : <strong>cécité traumatique</strong> (TDM en urgence + décompression chirurgicale rapide), diplopie par incarcération musculaire, plaies délabrantes des paupières.</li><li>Atteinte du <strong>nerf facial</strong> : examen de la motricité faciale chez le patient vigile, avant toute sédation.</li><li><strong>Pertes dentaires traumatiques</strong> : rechercher les dents luxées sur le terrain et les conditionner pour une éventuelle réimplantation.</li></ul>"},{"i":"3772fda90106","n":335,"o":"335-1","u":"Identifier une urgence","t":"Identifier les urgences vitales et fonctionnelles du traumatisé facial","q":"Comment évaluer le pronostic vital et fonctionnel initial d'un traumatisme maxillo-facial ?","a":"<p>Le pronostic vital est <strong>rarement engagé</strong> par un traumatisme maxillo-facial isolé. Cependant, le pronostic fonctionnel est <strong>presque toujours en question</strong> et doit être évalué rapidement.</p>"},{"i":"3c58b626038d","n":335,"o":"335-1","u":"Identifier une urgence","t":"Identifier les urgences vitales et fonctionnelles du traumatisé facial","q":"Quels sont les mécanismes d'asphyxie chez un traumatisé facial et quelle est la conduite à tenir ?","a":"<p>Les causes d'asphyxie comprennent :</p><ul><li>Inhalation de sang, dents, fragments de prothèse, ou vomissements</li><li>Hématome compressif du plancher buccal (fracture du corps mandibulaire)</li><li>Glossoptose (fracas mandibulaire, fracture biparasymphysaire)</li><li>Encombrement des voies aériennes supérieures (VAS)</li></ul><p>La conduite à tenir est :</p><ol><li><strong>Libération des VAS</strong> : compresse, aspiration, canule de Mayo</li><li>Si la liberté des VAS n'est pas maintenue : <strong>intubation orotrachéale</strong> (le plus souvent) ou nasotrachéale</li><li><strong>Trachéotomie</strong> en dernier recours</li></ol>"},{"i":"56d1032ee7b5","n":335,"o":"335-1","u":"Identifier une urgence","t":"Identifier les urgences vitales et fonctionnelles du traumatisé facial","q":"Quelles sont les sources d'hémorragie entraînant un choc hypovolémique chez un traumatisé facial et comment les prendre en charge initialement ?","a":"<p>Les sources d'hémorragie incluent :</p><ul><li><strong>Épistaxis</strong> (fractures OPN bilatérale, zygomato-maxillaire, Le Fort bilatérale)</li><li><strong>Otorragie</strong> (fracture de l'os tympanal/rocher)</li><li><strong>Stomatorragie</strong> (fracture du corps mandibulaire)</li><li>Plaies des parties molles</li></ul><p>La prise en charge initiale est :</p><ul><li><strong>Compression / clampage / ligature</strong> d'un vaisseau</li><li><strong>Réduction de fracture + blocage maxillo-mandibulaire</strong></li><li>Prise en charge spécifique de l'épistaxis : <strong>tamponnement antérieur, antéro-postérieur, embolisation de l'artère sphéno-palatine</strong></li></ul>"},{"i":"9bff9f3d079b","n":335,"o":"335-1","u":"Identifier une urgence","t":"Identifier les urgences vitales et fonctionnelles du traumatisé facial","q":"Quelles sont les situations à risque d'hémorragie sous-estimée chez un traumatisé facial ?","a":"<p>Les hémorragies peuvent être <strong>dégluties</strong> et donc sous-estimées, avec un risque de vomissements secondaires et d'inhalation. Il faut toujours considérer un traumatisé facial comme un <strong>traumatisé crânien et du rachis cervical</strong> jusqu'à preuve du contraire.</p>"},{"i":"cca2194116e7","n":335,"o":"335-1","u":"Identifier une urgence","t":"Identifier les urgences vitales et fonctionnelles du traumatisé facial","q":"Quelles sont les deux principales urgences vitales à rechercher face à un traumatisme maxillo-facial ?","a":"<p>Les deux principales urgences vitales sont :</p><ul><li>L'<strong>asphyxie</strong></li><li>Le <strong>choc hypovolémique (hémorragique)</strong></li></ul>"},{"i":"5fe07e174ce1","n":335,"o":"335-11","u":"Examens complémentaires","t":"Connaître les examens à réaliser dans le cadre d’une fracture de mandibule","q":"Quel est l'examen d'imagerie de première intention à réaliser pour le diagnostic d'une fracture du corps mandibulaire, et quand doit-il être complété ?","a":"<p>L'examen de première intention est l'<strong>orthopantomogramme</strong> (radiographie panoramique). Il est généralement suffisant pour poser le diagnostic.</p><p>Il peut être complété par un <strong>cliché de face basse</strong>. En cas de doute diagnostique, un <strong>scanner (TDM)</strong> avec des coupes axiales et coronales en fenêtre osseuse est indiqué.</p>"},{"i":"959fe5d49e27","n":335,"o":"335-11","u":"Examens complémentaires","t":"Connaître les examens à réaliser dans le cadre d’une fracture de mandibule","q":"Que permet de préciser la TDM dans le diagnostic des fractures mandibulaires ?","a":"<p>La TDM confirme la ou les fracture(s) et permet de préciser :</p><ul><li>Le <strong>siège</strong> de la fracture et son rapport au <strong>canal mandibulaire</strong>.</li><li>Les <strong>caractéristiques du trait</strong> (par exemple, simple ou comminutif).</li><li>Les <strong>déplacements</strong> (décalage, angulation, chevauchement).</li><li>L'<strong>état de la denture</strong>.</li></ul>"},{"i":"bb3c61c90363","n":335,"o":"335-11","u":"Examens complémentaires","t":"Connaître les examens à réaliser dans le cadre d’une fracture de mandibule","q":"Quels sont les examens d'imagerie à réaliser pour le diagnostic d'une fracture du condyle mandibulaire ?","a":"<p>Pour une fracture du condyle mandibulaire, il faut réaliser un <strong>orthopantomogramme</strong> (pour évaluer le profil et un éventuel déplacement axial) et une <strong>incidence de face basse</strong> (pour évaluer la face et un éventuel déplacement frontal).</p><p>La <strong>TDM</strong> est <strong>indispensable</strong> pour la décision thérapeutique, notamment grâce à la reconstruction 3D qui permet de préciser la hauteur du trait, la taille du fragment et les déplacements.</p>"},{"i":"56e7092c593e","n":335,"o":"335-18","u":"Diagnostic positif","t":"Connaître les signes cliniques présents dans les fractures du plancher de l’orbite","q":"Quel est le piège sémiologique à connaître dans les fractures du plancher de l'orbite, et quelle est la triade diagnostique principale ?","a":"<p>Le piège sémiologique est l'<strong>absence de douleur à la palpation des reliefs osseux</strong>, contrairement aux fractures latérofaciales.</p><p>Le diagnostic repose principalement sur la triade :</p><ul><li>La <strong>diplopie</strong></li><li>L'<strong>hypoesthésie du nerf infra-orbitaire (V2)</strong></li><li>L'<strong>imagerie</strong></li></ul>"},{"i":"90ea5cc7ef99","n":335,"o":"335-18","u":"Diagnostic positif","t":"Connaître les signes cliniques présents dans les fractures du plancher de l’orbite","q":"Quelle est la présentation clinique évocatrice d'une fracture par \"blow-out\" du plancher de l'orbite chez l'adulte ?","a":"<p>La fracture par \"blow-out\" ou en trappe chez l'adulte, se manifeste par une <strong>ophtalmoplégie verticale totale et douloureuse</strong>, ou une limitation de l'élévation du regard sans ophtalmoplégie totale.</p><p>On peut également observer une <strong>énophtalmie</strong> et/ou une <strong>dystopie</strong> (souvent tardives, après la résorption de l'œdème).</p>"},{"i":"dc4767ccd5d8","n":335,"o":"335-18","u":"Diagnostic positif","t":"Connaître les signes cliniques présents dans les fractures du plancher de l’orbite","q":"Quels sont les signes cliniques communs, mais inconstants, pouvant être présents lors d'une fracture du plancher de l'orbite ?","a":"<ul><li><strong>Œdème</strong> et/ou <strong>ecchymose périorbitaire</strong></li><li><strong>Chémosis</strong> (œdème de la conjonctive)</li><li><strong>Hémorragie conjonctivale</strong></li><li><strong>Emphysème palpébral</strong></li><li>Une <strong>hypoesthésie</strong> du territoire du <strong>nerf infra-orbitaire (V2)</strong> : lèvre supérieure, joue, aile du nez</li><li><strong>Diplopie verticale binoculaire</strong></li></ul>"},{"i":"678329f3675e","n":335,"o":"335-19","u":"Identifier une urgence","t":"Reconnaître les critères d’incarcération musculaire dans une fracture du plancher de l’orbite","q":"Pourquoi l'incarcération musculaire dans une fracture du plancher de l'orbite est-elle une urgence thérapeutique et quelles en sont les conséquences redoutées ?","a":"<p>L'incarcération musculaire est une <strong>urgence thérapeutique vraie</strong> car l'absence de prise en charge rapide (dans les heures) entraîne une <strong>fibrose musculaire par ischémie</strong>. Les conséquences sont une <strong>diplopie séquellaire</strong> le plus souvent définitive et un risque majeur d'<strong>amblyopie chez l'enfant</strong>. Le <strong>mouchage est contre-indiqué</strong> dans ce contexte.</p>"},{"i":"a60b340752c1","n":335,"o":"335-19","u":"Identifier une urgence","t":"Reconnaître les critères d’incarcération musculaire dans une fracture du plancher de l’orbite","q":"Quels sont les critères cliniques d'une incarcération musculaire du muscle droit inférieur dans une fracture du plancher de l'orbite ?","a":"<p>Les critères cliniques d'incarcération sont :</p><ul><li>Un <strong>syndrome vagal</strong> (vomissements, douleur intense, bradycardie).</li><li>Une <strong>ophtalmoplégie verticale totale et douloureuse</strong>.</li><li>Une <strong>limitation de l'élévation du regard</strong>.</li></ul>"},{"i":"b8ddab309f46","n":335,"o":"335-19","u":"Identifier une urgence","t":"Reconnaître les critères d’incarcération musculaire dans une fracture du plancher de l’orbite","q":"Quelle est la particularité radiologique à rechercher au scanner en cas de fracture orbitaire avec incarcération musculaire ?","a":"<p>Au scanner (TDM), le trait de fracture peut être <strong>peu visible</strong> (fracture en trappe « refermée ») et l'incarcération est caractérisée par une <strong>image en sablier</strong> en coupe coronale, due à l'incarcération musculo-graisseuse.</p>"},{"i":"175f9d482cda","n":335,"o":"335-2","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire et de l’examen clinique à réaliser dans le cadre d’un traumatisme facial","q":"Quels sont les éléments clés à rechercher lors de l'inspection d'un traumatisme facial ?","a":"<p>L'inspection doit porter sur :</p><ul><li>Le <strong>revêtement cutané</strong> : recherche de plaie, ecchymose, corps étrangers, œdème localisé ou « faciès lunaire ».</li><li>L'<strong>hémorragie extériorisée</strong>.</li><li>La <strong>rhinorrhée aqueuse</strong> (signe de brèche méningée potentielle).</li><li>La <strong>déformation ou l'asymétrie</strong> témoignant d'une fracture déplacée (à réévaluer à distance en cas d'œdème).</li></ul>"},{"i":"519c24d475f1","n":335,"o":"335-2","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire et de l’examen clinique à réaliser dans le cadre d’un traumatisme facial","q":"Quels sont les signes directs et indirects de fracture à rechercher lors de la palpation faciale ?","a":"<p>La palpation (de haut en bas, en finissant par la zone traumatisée) permet de rechercher :</p><ul><li><strong>Signes directs</strong> : <strong>douleur exquise</strong> au trait de fracture, <strong>déplacement osseux</strong> (asymétrie), perception d'une <strong>« marche d'escalier »</strong>, <strong>mobilité anormale</strong>.</li><li><strong>Signe indirect</strong> : <strong>emphysème sous-cutané</strong> (traduisant la fracture d'une paroi de cavité aérienne), notamment au niveau du sinus maxillaire, sinus frontal, cellules ethmoïdales ou plancher de l'orbite, déclenché par mouchage, éternuement ou manœuvre de Valsalva.</li></ul>"},{"i":"74852e51d600","n":335,"o":"335-2","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire et de l’examen clinique à réaliser dans le cadre d’un traumatisme facial","q":"Comment évaluer la motricité et la sensibilité de la face lors de l'examen clinique d'un traumatisme facial ?","a":"<p>L'évaluation porte sur les territoires des nerfs crâniens :</p><ul><li><strong>Nerf III (oculomoteur)</strong> : élévation de la paupière supérieure.</li><li><strong>Nerf V (trijumeau) moteur</strong> : muscles masticateurs.</li><li><strong>Nerf VII (facial)</strong> : muscles peauciers (partie supérieure : hausser les sourcils, fermer les yeux ; partie inférieure : gonfler les joues, sourire).</li><li><strong>Nerf V1 (ophtalmique sensitif)</strong> : cornée, hémifront, paupière supérieure, racine et dorsum du nez.</li><li><strong>Nerf V2 (maxillaire sensitif)</strong> : aile nasale, partie haute de la joue, hémilèvre supérieure, hémiarcade dentaire supérieure.</li><li><strong>Nerf V3 (mandibulaire mixte)</strong> : hémilèvre inférieure, menton, partie basse de la joue, hémiarcade dentaire inférieure, 2/3 antérieurs de la langue.</li></ul>"},{"i":"8f3db7ab3291","n":335,"o":"335-2","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire et de l’examen clinique à réaliser dans le cadre d’un traumatisme facial","q":"Quelles sont les explorations endocavitaires et l'examen des fonctions à pratiquer en cas de traumatisme facial ?","a":"<p>Il convient de réaliser :</p><ul><li>Examen des <strong>fosses nasales</strong> (rhinoscopie antérieure) : épistaxis, déviation/luxation de la cloison, <strong>hématome de cloison (à évacuer en urgence)</strong>, rhinorrhée aqueuse (suspicion de brèche méningée).</li><li>Examen de la <strong>cavité buccale</strong> : modification de l'articulé dentaire, lésions dentaires (valeur médico-légale), palpation endobuccale (mobilité de l'arcade = Le Fort, mobilité d'un secteur = fracture alvéolodentaire).</li><li>Examen des <strong>conduits auditifs externes (CAE)</strong> : caillots, plaie cutanée (fracture os tympanal), état du tympan.</li><li>Examen des <strong>fonctions</strong> : manducation (articulation temporo-mandibulaire, occlusion, trismus), ophtalmologique (acuité visuelle, diplopie, pupilles/réflexe photomoteur, dystopie oculaire), neurologique (conscience, anosmie, rhinorrhée de liquide céphalo-rachidien).</li></ul>"},{"i":"fb8b9fb121c2","n":335,"o":"335-2","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire et de l’examen clinique à réaliser dans le cadre d’un traumatisme facial","q":"Quels sont les éléments de l'interrogatoire à rechercher face à un traumatisme facial ?","a":"<p>L'interrogatoire doit préciser :</p><ul><li>Les <strong>circonstances</strong> : date, heure, mécanisme (agression, AVP, accident de travail/domestique/sport, morsure), point d'impact, direction et intensité du choc.</li><li>Les <strong>signes fonctionnels</strong> : craquement lors du choc, perte de connaissance initiale, douleurs, gènes manducatrices (modification de l'articulé dentaire, limitation d'ouverture buccale), visuelles (baisse d'acuité visuelle, diplopie), respiratoires (obstruction nasale, anosmie, épistaxis) et phonatoires.</li><li>Les <strong>antécédents</strong> : anomalie occlusale préexistante, photographies prétraumatiques.</li></ul>"},{"i":"2d528b5597d1","n":335,"o":"335-23","u":"Diagnostic positif","t":"Connaître les signes cliniques présents dans les fractures des os nasaux","q":"Quels sont les signes visibles à l'inspection lors d'une fracture des os nasaux ?","a":"<p>À l'inspection, une fracture des os nasaux se manifeste par un <strong>hématome du dorsum</strong>, des <strong>ecchymoses en lunettes</strong>. On peut également observer une <strong>déformation du nez</strong>, comme un « nez couché » en cas de choc latéral ou une ensellure nasale après un choc antéro-postérieur, souvent masquée par l'œdème.</p>"},{"i":"6803ca5fc6a4","n":335,"o":"335-23","u":"Diagnostic positif","t":"Connaître les signes cliniques présents dans les fractures des os nasaux","q":"Quels sont les signes fonctionnels classiques d'une fracture des os nasaux ?","a":"<p>Devant une fracture des os nasaux, les signes fonctionnels classiques sont un <strong>craquement</strong> ressenti, une <strong>douleur</strong> intense, une <strong>épistaxis bilatérale</strong> (témoignant d'une plaie muqueuse endonasale et donc du caractère ouvert de la fracture), et une <strong>obstruction nasale</strong>.</p>"},{"i":"b9a931604f07","n":335,"o":"335-23","u":"Diagnostic positif","t":"Connaître les signes cliniques présents dans les fractures des os nasaux","q":"Quels sont les signes retrouvés à l'examen clinique spécifique d'une fracture des os nasaux ?","a":"<p>L'examen clinique d'une fracture des os nasaux révèle une <strong>douleur élective</strong> et une <strong>mobilité anormale « en touche de piano »</strong> à la palpation. La rhinoscopie antérieure peut montrer une <strong>luxation de la cloison nasale</strong>, un saignement actif (épistaxis), un <strong>hématome de la cloison</strong> (urgence nécessitant un drainage), et potentiellement une <strong>rhinoliquorrhée</strong> en cas de brèche associée.</p>"},{"i":"e14295f59c3b","n":335,"o":"335-23","u":"Diagnostic positif","t":"Connaître les signes cliniques présents dans les fractures des os nasaux","q":"Comment identifier une fracture nasomaxillaire, forme particulière de fracture faciale impliquant les os nasaux ?","a":"<p>En cas de fracture nasomaxillaire, qui implique les os nasaux et les apophyses frontales des maxillaires, on peut palper une <strong>« marche d'escalier »</strong> à la partie médiale du rebord infra-orbitaire.</p>"},{"i":"0a20f4b37876","n":335,"o":"335-28","u":"Identifier une urgence","t":"Connaître les éléments cliniques d’une brèche cérébro-spinale dans le cadre d’un traumatisme facial","q":"Quelle est la principale complication grave d'une brèche ostéoméningée et quelle est la prise en charge initiale ?","a":"<p>La principale complication grave d'une brèche ostéoméningée est la <strong>méningite bactérienne</strong>, le plus souvent due au <strong>pneumocoque</strong> ou à <strong><em>Haemophilus influenzae</em></strong>. Elle peut évoluer vers un empyème ou un abcès.</p><p>La prise en charge initiale comprend :</p><ul><li>La <strong>vaccination anti-pneumococcique</strong> et <strong>anti-<em>Haemophilus</em></strong>.</li><li>La réalisation d'une <strong>Tomodensitométrie (TDM) en urgence</strong> pour localiser la brèche et rechercher des signes de pneumencéphalie.</li></ul>"},{"i":"1841046e4abe","n":335,"o":"335-28","u":"Identifier une urgence","t":"Connaître les éléments cliniques d’une brèche cérébro-spinale dans le cadre d’un traumatisme facial","q":"Devant quels types de traumatismes faciaux doit-on rechercher systématiquement une brèche ostéoméningée ?","a":"<p>Il faut rechercher une brèche ostéoméningée devant tout traumatisme crânien (TC) associé à un traumatisme de l'étage moyen de la face, tels que :</p><ul><li>Les fractures de type <strong>Le Fort 2 ou 3</strong>.</li><li>Les traumatismes complexes naso-ethmoïdo-maxillo-orbitaux (<strong>CNEMFO</strong>).</li><li>Les fractures des <strong>os nasaux</strong>.</li></ul>"},{"i":"33f2852cde20","n":335,"o":"335-28","u":"Identifier une urgence","t":"Connaître les éléments cliniques d’une brèche cérébro-spinale dans le cadre d’un traumatisme facial","q":"Quels sont les signes cliniques orientant vers une brèche ostéoméningée post-traumatique au niveau du visage et du crâne ?","a":"<p>Les signes cliniques orientant vers une brèche ostéoméningée sont :</p><ul><li>Une <strong>rhinorrhée de liquide céphalorachidien (LCS)</strong> : écoulement clair, « eau de roche », recherché tête penchée en avant ou à la manœuvre de Valsalva.</li><li>Une <strong>ecchymose « en lunettes »</strong>.</li><li>Une <strong>anosmie</strong>, suggérant une section des filets olfactifs ou une fracture de l'ethmoïde.</li><li>Dans les cas de fracture du rocher (variante de brèche de la base du crâne) : une <strong>ecchymose rétromastoïdienne</strong> (signe de Battle), une <strong>otoliquorrhée</strong> ou <strong>otorragie</strong>, une <strong>hypoacousie</strong> et une <strong>paralysie faciale périphérique</strong>.</li></ul>"},{"i":"3a3f4e9cac23","n":335,"o":"335-28","u":"Identifier une urgence","t":"Connaître les éléments cliniques d’une brèche cérébro-spinale dans le cadre d’un traumatisme facial","q":"Comment confirmer la présence de LCS dans un écoulement suspect de rhinorrhée ou otoliquorrhée ?","a":"<p>La confirmation de la présence de LCS se fait par :</p><ul><li>La recherche de <strong>glucose à la bandelette urinaire</strong>, bien que cette méthode soit moins spécifique.</li><li>Des tests plus spécifiques tels que la détection de la <strong>β2-transferrine</strong>, de la <strong>protéine tau</strong> ou de la <strong>β-trace</strong> dans l'écoulement.</p></li></ul>"},{"i":"f0b165836517","n":335,"o":"335-28","u":"Identifier une urgence","t":"Connaître les éléments cliniques d’une brèche cérébro-spinale dans le cadre d’un traumatisme facial","q":"Quelle est la définition d'une brèche ostéoméningée (BOM) dans le contexte d'un traumatisme cranio-facial ?","a":"<p>Une brèche ostéoméningée (BOM) est une communication directe entre les espaces méningés et les cavités aériennes (sinus paranasaux, oreille moyenne) et le milieu extérieur. Elle résulte d'une <strong>fracture de la base du crâne</strong> associée à une <strong>déchirure de la dure-mère</strong>.</p>"},{"i":"320cf8a33e27","n":335,"o":"335-3","u":"Examens complémentaires","t":"Connaître les examens à réaliser en première intention dans le cadre d’un traumatisme facial en fonction des orientations diagnostiques","q":"Quels sont les examens d'imagerie de première intention recommandés pour une suspicion de fracture du corps mandibulaire versus du condyle mandibulaire ?","a":"<ul><li>Pour une fracture du corps mandibulaire : un <strong>orthopantomogramme (panoramique dentaire)</strong> ± un cliché face basse. Une TDM est réalisée en cas de doute.</li><li>Pour une fracture du condyle mandibulaire : un <strong>orthopantomogramme</strong> et une incidence <strong>face basse</strong>. Une <strong>TDM est indispensable</strong> à la décision thérapeutique.</li></ul>"},{"i":"91722d193397","n":335,"o":"335-3","u":"Examens complémentaires","t":"Connaître les examens à réaliser en première intention dans le cadre d’un traumatisme facial en fonction des orientations diagnostiques","q":"Quelle est l'imagerie de première intention pour les fractures zygomato-maxillaires, plancher de l'orbite, CNEMFO ou de type Le Fort ?","a":"<p>Pour ces types de fractures, une <strong>TDM du massif facial est indispensable</strong>. Pour le plancher de l'orbite, la CNEMFO et les fractures de Le Fort, des coupes axiales et des <strong>reconstructions coronales et sagittales centrées sur l'orbite</strong> sont nécessaires.</p>"},{"i":"9b40232e4349","n":335,"o":"335-3","u":"Examens complémentaires","t":"Connaître les examens à réaliser en première intention dans le cadre d’un traumatisme facial en fonction des orientations diagnostiques","q":"Quels examens biologiques sont à réaliser en première intention devant un traumatisme facial ?","a":"<ul><li><strong>Bilan pré-opératoire / hémorragie</strong> : <strong>bilan d'hémostase</strong>, <strong>NFS</strong>, <strong>groupage ABO-Rhésus + RAI</strong>.</li><li><strong>Évaluation d'un traumatisme crânien (TC) associé</strong> : <strong>glycémie</strong>, <strong>ionogramme</strong>, <strong>alcoolémie</strong>, <strong>recherche de toxiques</strong>.</li></ul>"},{"i":"b41b3860fab6","n":335,"o":"335-3","u":"Examens complémentaires","t":"Connaître les examens à réaliser en première intention dans le cadre d’un traumatisme facial en fonction des orientations diagnostiques","q":"Quelle est l'imagerie de première intention indiquée pour un traumatisme nasal ?","a":"<p>Aucune imagerie n'est indiquée en première intention pour un traumatisme nasal. Une <strong>TDM non injectée</strong> peut être envisagée à <strong>J5</strong> si l'œdème rend l'examen clinique incertain.</p>"},{"i":"fc4fa40433f7","n":335,"o":"335-3","u":"Examens complémentaires","t":"Connaître les examens à réaliser en première intention dans le cadre d’un traumatisme facial en fonction des orientations diagnostiques","q":"Quel est l'examen d'imagerie de première intention à réaliser pour le diagnostic des fractures du massif facial, après avoir éliminé une lésion crânienne ou cervicale ?","a":"<p>L'examen d'imagerie de première intention est la <strong>TDM (scanner) non injectée</strong>. Elle offre une haute définition, des reconstructions 3D et est réalisable quel que soit l'état neurologique du patient.</p>"},{"i":"4397dde80bad","n":335,"o":"335-30","u":"Définition","t":"Connaître les différents traumatismes crâniens de l’enfant","q":"Quelle est l'incidence et la sévérité des traumatismes crâniens chez l'enfant de moins de 12 ans et chez l'adolescent ?","a":"<p>Chez l'enfant de moins de 10-12 ans, les traumatismes crâniens sont <strong>très fréquents</strong> mais le plus souvent <strong>bénins</strong>. Chez le grand enfant ou l'adolescent (15-18 ans), ils représentent la <strong>première cause de mortalité et de handicap sévère</strong>.</p>"},{"i":"7c528e7f9388","n":335,"o":"335-30","u":"Définition","t":"Connaître les différents traumatismes crâniens de l’enfant","q":"Quels sont les trois principaux cadres étiologiques des traumatismes crâniens chez l'enfant et leurs caractéristiques ?","a":"<ul><li>Le <strong>traumatisme crânien accidentel</strong> se manifeste par un céphalhématome (collection limitée par les sutures) ou une fracture linéaire simple, voire une embarrure.</li><li>Le <strong>traumatisme crânien obstétrical</strong> peut entraîner un céphalhématome (lésion la plus fréquente, souvent spontanément résolutive) ou des fractures, favorisées par l'utilisation de forceps.</li><li>Le <strong>traumatisme crânien non accidentel</strong> correspond au syndrome du bébé secoué.</li></ul>"},{"i":"8e3d3f6c7a1f","n":335,"o":"335-30","u":"Définition","t":"Connaître les différents traumatismes crâniens de l’enfant","q":"Quelles sont les particularités anatomo-physiologiques de l'enfant impactant les traumatismes crâniens, et leurs conséquences ?","a":"<ul><li>La <strong>disproportion crâne-corps</strong> entraîne une inertie de la tête, favorisant l'arrachement des veines « en pont », observé notamment dans les lésions du bébé secoué.</li><li>L'<strong>immaturité cérébrale</strong> (cerveau peu myélinisé) rend l'enfant plus vulnérable à l'ischémie et aux convulsions, mais sa <strong>plasticité cérébrale</strong> permet une bonne récupération des lésions primaires.</li><li>La <strong>masse sanguine faible</strong> expose au risque de choc hémorragique en cas de plaie du scalp ou de céphalhématome, parfois avant l'apparition de signes neurologiques.</li><li>L'<strong>immaturité squelettique</strong> (crâne souple) peut entraîner des contusions sous-fracturaires et des <strong>fractures évolutives</strong> (fracture associée à une déchirure durale et une hernie cérébrale qui s'aggrave avec la croissance).</li></ul>"},{"i":"3c28e8739f28","n":335,"o":"335-31","u":"Identifier une urgence","t":"Traumatismes crâniens de l’enfant : évaluer la gravité et les complications précoces","q":"Quelle est la définition et la physiopathologie principale du Syndrome du Bébé Secoué (SBS) ?","a":"<p>Le Syndrome du Bébé Secoué (SBS) est un traumatisme non accidentel survenant le plus souvent chez le <strong>nourrisson de moins de 1 an</strong> (deux tiers des cas avant 6 mois). Il résulte de <strong>décélérations antéropostérieures</strong> violentes, provoquant l'arrachement des <strong>veines « en pont »</strong>, ce qui entraîne un <strong>hématome sous-dural</strong>. Sa mortalité est d'environ 10 %.</p>"},{"i":"41cd1325d452","n":335,"o":"335-31","u":"Identifier une urgence","t":"Traumatismes crâniens de l’enfant : évaluer la gravité et les complications précoces","q":"Quels sont les signes cliniques et les examens complémentaires à réaliser en cas de suspicion de Syndrome du Bébé Secoué (SBS) ?","a":"<p>La clinique du SBS est variée et peut inclure :</p><ul><li>Des <strong>troubles de la vigilance</strong> voire un coma.</li><li>Des <strong>convulsions</strong>.</li><li>Des <strong>signes d'HTIC</strong> (macrocrânie, fontanelle bombante, vomissements, strabisme, régression psychomotrice).</li><li>Une <strong>hypotonie axiale</strong>.</li><li>Des <strong>signes cutanés</strong> (ecchymoses, à photographier systématiquement).</li><li>Des <strong>lésions ORL</strong>.</li></ul><p>Le bilan complémentaire comprend :</p><ul><li>Un <strong>scanner cérébral</strong> (recherche d'hématome sous-dural, HSD).</li><li>Un <strong>fond d'œil précoce</strong> (recherche d'hémorragies rétiniennes caractéristiques, qui disparaissent en 1 semaine).</li><li>Une <strong>IRM cérébrale</strong>.</li><li>Des <strong>radiographies du squelette entier</strong>.</li><li>Une <strong>NFS</strong> et un bilan d'<strong>hémostase</strong>.</li></ul><p>Tout hématome sous-dural du nourrisson doit faire évoquer une maltraitance, et un <strong>signalement judiciaire est une obligation légale</strong> qui dégage le médecin du secret médical.</p>"},{"i":"ba5dde4924a6","n":335,"o":"335-31","u":"Identifier une urgence","t":"Traumatismes crâniens de l’enfant : évaluer la gravité et les complications précoces","q":"Quels sont les signes spécifiques de gravité évocateurs d'une souffrance cérébrale ou d'une HTIC chez l'enfant polytraumatisé ?","a":"<p>Devant un traumatisme crânien chez l'enfant, certains signes doivent faire évoquer une souffrance cérébrale ou une hypertension intracrânienne (HTIC) :</p><ul><li>Au niveau du <strong>contact visuel</strong> : regard « en coucher de soleil », errance du regard, ou perte du contact oculaire.</li><li>Une <strong>fontanelle antérieure bombante</strong> (présente jusqu'à l'âge de 15-18 mois), à palper systématiquement.</li><li>Une <strong>bradycardie</strong>, qui peut traduire une HTIC.</li><li>Une <strong>pâleur</strong> et des <strong>signes de choc hémorragique</strong> (nécessitant une NFS pour évaluer la perte sanguine sur le scalp ou un céphalhématome).</li></ul>"},{"i":"f4374997345d","n":335,"o":"335-31","u":"Identifier une urgence","t":"Traumatismes crâniens de l’enfant : évaluer la gravité et les complications précoces","q":"Quelles sont les complications précoces communes des traumatismes crâniens chez l'enfant ?","a":"<p>Les complications précoces communes des traumatismes crâniens chez l'enfant incluent :</p><ul><li>L'<strong>hématome extra-dural</strong>.</li><li>L'<strong>hématome sous-dural</strong>.</li><li>La <strong>fracture évolutive</strong> (avec risque de déchirure durale).</li><li>L'<strong>embarrure</strong>.</li><li>L'<strong>œdème cérébral</strong>.</li><li>Les <strong>convulsions</strong>.</li></ul>"},{"i":"306bd8e1766c","n":335,"o":"335-4","u":"Identifier une urgence","t":"Connaître les critères de gravité d’un traumatisme facial","q":"Quels sont les contextes (terrain ou co-lésions) qui aggravent la prise en charge d'un traumatisme facial ?","a":"<p>Certains contextes ou associations lésionnelles aggravent un traumatisme facial :</p><ul><li>Le <strong>polytraumatisme</strong>.</li><li>L'association à un <strong>traumatisme crânien (TC)</strong>.</li><li>L'association à un <strong>traumatisme du rachis cervical</strong>.</li><li>La présence d'une <strong>brèche méningée</strong>.</li><li>Une <strong>atteinte fonctionnelle ophtalmologique</strong>.</li><li>Les <strong>traumatismes balistiques</strong>, qui impliquent des urgences hémorragiques et respiratoires.</li></ul>"},{"i":"3fd6b6a6743f","n":335,"o":"335-4","u":"Identifier une urgence","t":"Connaître les critères de gravité d’un traumatisme facial","q":"Quels sont les trois grands axes permettant de juger de la gravité d'un traumatisme facial ?","a":"<p>La gravité d'un traumatisme facial s'évalue selon :</p><ul><li>Le retentissement <strong>vital</strong>.</li><li>Le retentissement <strong>fonctionnel</strong>.</li><li>Les <strong>associations lésionnelles</strong>.</li></ul>"},{"i":"9668b04e850e","n":335,"o":"335-4","u":"Identifier une urgence","t":"Connaître les critères de gravité d’un traumatisme facial","q":"Quel est le \"dogme\" concernant l'évaluation initiale de tout traumatisé facial ?","a":"<p>Le dogme est le suivant : <strong>tout traumatisé facial est un traumatisé crânien et un traumatisé du rachis cervical jusqu'à preuve du contraire</strong>.</p>"},{"i":"c3b63c782748","n":335,"o":"335-4","u":"Identifier une urgence","t":"Connaître les critères de gravité d’un traumatisme facial","q":"Quels sont les principaux signes de gravité d'un traumatisme facial imposant une urgence extrême ?","a":"<p>Les signes d'urgence extrême en cas de traumatisme facial sont :</p><ul><li>La présence d'une <strong>hémorragie extériorisée</strong> (stomatorragie, épistaxis, otorragie, plaie hémorragique).</li><li>La <strong>cécité traumatique</strong> (nécessitant un TDM en urgence et potentiellement une décompression chirurgicale).</li></ul>"},{"i":"dce552ff7bc1","n":335,"o":"335-4","u":"Identifier une urgence","t":"Connaître les critères de gravité d’un traumatisme facial","q":"Quels sont les éléments définissant un traumatisme facial grave (hors urgence extrême) ?","a":"<p>Un traumatisme facial est considéré comme grave dans les situations suivantes :</p><ul><li>Une <strong>fracture panfaciale</strong> (atteignant l'étage moyen et la mandibule).</li><li>Une fracture irradiant aux <strong>confins craniofaciaux</strong> avec une complication neuro-méningée.</li></ul>"},{"i":"00a97f2125a6","n":335,"o":"335-7","u":"Diagnostic positif","t":"Connaître le traumatisme dentaire nécessitant une prise en charge urgente (par exemple une luxation dentaire)","q":"Quelle est la conduite à tenir face à une luxation totale (avulsion) d'une dent lactéale ?","a":"<p>Pour une dent lactéale, il ne faut <strong>PAS réimplanter</strong>. La conduite à tenir est la mise en place d'un <strong>mainteneur d'espace</strong> pour éviter de léser le germe de la dent définitive sous-jacente.</p>"},{"i":"81503bc40224","n":335,"o":"335-7","u":"Diagnostic positif","t":"Connaître le traumatisme dentaire nécessitant une prise en charge urgente (par exemple une luxation dentaire)","q":"Quelle est la prise en charge urgente d'une luxation partielle (subluxation) d'une dent ?","a":"<p>En cas de luxation partielle (dent mobile, douloureuse, égressée avec saignement au collet), la prise en charge urgente consiste en une <strong>réduction</strong> (réimpaction) et une <strong>contention par collage</strong> aux dents adjacentes.</p>"},{"i":"986d20a5fec0","n":335,"o":"335-7","u":"Diagnostic positif","t":"Connaître le traumatisme dentaire nécessitant une prise en charge urgente (par exemple une luxation dentaire)","q":"Quelle est la prise en charge urgente d'une luxation totale (avulsion) d'une dent définitive ?","a":"<p>La prise en charge est urgente si elle a lieu <strong>moins d'une heure après l'expulsion</strong>. Il faut <strong>conserver la dent en milieu humide</strong> (sérum physiologique + pénicilline, salive ou lait à défaut) puis procéder à la <strong>réimplantation</strong> et à une <strong>contention</strong> au plus vite.</p>"},{"i":"b9df10d69f80","n":335,"o":"335-7","u":"Diagnostic positif","t":"Connaître le traumatisme dentaire nécessitant une prise en charge urgente (par exemple une luxation dentaire)","q":"Comment est définie une urgence en traumatologie dentaire selon le contexte de l'Item 335 ?","a":"<p>L'urgence en traumatologie dentaire est définie par la nécessité d'un <strong>geste odontologique immédiat</strong> pour <strong>sauver la dent</strong> ou le <strong>germe dentaire</strong>.</p>"},{"i":"fd97d9255cd9","n":335,"o":"335-7","u":"Diagnostic positif","t":"Connaître le traumatisme dentaire nécessitant une prise en charge urgente (par exemple une luxation dentaire)","q":"Quelle est la prise en charge urgente d'une fracture de l'os alvéolaire ?","a":"<p>La prise en charge urgente d'une fracture de l'os alvéolaire, caractérisée par la mobilité d'un bloc de dents intactes, est la <strong>réduction</strong> du bloc fracturé et sa <strong>contention</strong>.</p>"},{"i":"fe3c47ec1ea5","n":335,"o":"335-7","u":"Diagnostic positif","t":"Connaître le traumatisme dentaire nécessitant une prise en charge urgente (par exemple une luxation dentaire)","q":"Quelle est la prise en charge d'urgence d'une fracture de la couronne dentaire avec exposition pulpaire ?","a":"<p>Si la pulpe est exposée lors d'une fracture de la couronne, la prise en charge d'urgence implique une <strong>dévitalisation</strong> de la dent suivie d'un <strong>traitement endodontique</strong>. Si la pulpe n'est pas exposée, un simple vernis protecteur suffit.</p>"},{"i":"0f9d8a79be71","n":335,"o":"335-9","u":"Diagnostic positif","t":"Connaître les signes cliniques présents dans les fractures de mandibule (pour l’ensemble des fractures, condyle inclus)","q":"Quels sont les signes cliniques spécifiques d'une fracture du corps mandibulaire ou de l'angle mandibulaire ?","a":"<p>Les signes cliniques spécifiques d'une fracture du corps ou de l'angle mandibulaire comprennent :</p><ul><li>Une <strong>mobilité osseuse anormale</strong>.</li><li>Une <strong>blessure de la muqueuse gingivale</strong> entre les deux dents bordant le foyer de fracture.</li><li>Une <strong>modification de l'articulé dentaire</strong> (chevauchement, angulation, décalage).</li><li>Le <strong>Signe de Vincent</strong> (hypo/anesthésie labiomentonnière par atteinte du V3) si la fracture est déplacée au regard du canal mandibulaire ; ce signe est <strong>jamais présent</strong> dans une fracture symphysaire.</li></ul>"},{"i":"4943198cb3b5","n":335,"o":"335-9","u":"Diagnostic positif","t":"Connaître les signes cliniques présents dans les fractures de mandibule (pour l’ensemble des fractures, condyle inclus)","q":"Quels sont les signes cliniques d'une fracture condylienne de la mandibule ?","a":"<p>Les signes cliniques d'une fracture condylienne de la mandibule sont :</p><ul><li>Une <strong>douleur préauriculaire</strong> du côté fracturé.</li><li>Une <strong>limitation de l'ouverture buccale</strong> et de la propulsion.</li><li>Une <strong>otorragie</strong> par plaie du conduit auditif externe (suggérant une fracture de l'os tympanal).</li></ul>"},{"i":"8025888ede8d","n":335,"o":"335-9","u":"Diagnostic positif","t":"Connaître les signes cliniques présents dans les fractures de mandibule (pour l’ensemble des fractures, condyle inclus)","q":"Comment les troubles de l'articulé dentaire se manifestent-ils dans les formes unilatérales et bilatérales des fractures condyliennes ?","a":"<p>Les troubles de l'articulé dentaire se manifestent différemment selon la forme :</p><ul><li><strong>Forme unilatérale</strong> : un <strong>raccourcissement du ramus homolatéral</strong>, une <strong>latérodéviation du côté fracturé</strong> à l'ouverture et à la propulsion, un <strong>contact molaire prématuré</strong> du côté fracturé avec une <strong>pseudobéance controlatérale</strong>.</li><li><strong>Forme bilatérale</strong> : un <strong>contact molaire prématuré bilatéral</strong> et une <strong>pseudobéance antérieure</strong> (proche d'un Le Fort).</li><li><strong>Forme trifocale (condyles bilatéraux + corps)</strong> : une <strong>valgisation des angles</strong> mandibulaire, entraînant un <strong>élargissement du tiers inférieur de la face</strong>.</li></ul>"},{"i":"b9b4c426a6a1","n":335,"o":"335-9","u":"Diagnostic positif","t":"Connaître les signes cliniques présents dans les fractures de mandibule (pour l’ensemble des fractures, condyle inclus)","q":"Quand faut-il suspecter une fracture du rocher en cas d'otorragie post-traumatique, et la différencier d'une fracture condylienne ?","a":"<p>En cas d'otorragie post-traumatique, une fracture du rocher doit être suspectée et différenciée d'une fracture condylienne (avec atteinte de l'os tympanal) si les signes suivants sont présents :</p><ul><li>Un <strong>hémotympan</strong>.</li><li>Une <strong>surdité de perception</strong>.</li><li>Une <strong>paralysie faciale</strong>.</li><li>Des <strong>vertiges</strong>.</li></ul>"},{"i":"f73357ba308d","n":335,"o":"335-9","u":"Diagnostic positif","t":"Connaître les signes cliniques présents dans les fractures de mandibule (pour l’ensemble des fractures, condyle inclus)","q":"Quels sont les symptômes cardinaux d'une fracture du corps mandibulaire ou de l'angle mandibulaire ?","a":"<p>Les symptômes cardinaux d'une fracture du corps ou de l'angle mandibulaire sont :</p><ul><li>Une <strong>stomatorragie</strong> et une <strong>sialorrhée</strong>.</li><li>Une <strong>douleur à la mastication</strong>.</li><li>Un <strong>trismus antalgique</strong>.</li></ul>"}]};